# ---------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------

@dataclass(frozen=True)
class _SlotKey:
    """Slot identity dùng để compare TKB pattern (không tính ten_bai/ppct)."""
    thu: int
    buoi_idx: int
    tiet_idx: int
    lop_id: str
    mon_id: str


@dataclass
class YearTKBPattern:
    """1 pattern TKB — set các slot (lop, mon) ở từng (thu, buoi, tiet)."""
    pattern_id: int
    weeks: list[int] = field(default_factory=list)
    slots: list[_SlotKey] = field(default_factory=list)
    sample_data: dict[str, list] = field(default_factory=dict)  # row_key -> [WeekData refs]

    def short_label(self) -> str:
        if not self.weeks:
            return f"P{self.pattern_id} (empty)"
        if len(self.weeks) == 1:
            return f"P{self.pattern_id} (Tuần {self.weeks[0]}) — {len(self.slots)} slot"
        first, last = min(self.weeks), max(self.weeks)
        cont = list(range(first, last + 1)) == sorted(self.weeks)
        if cont:
            return f"P{self.pattern_id} (Tuần {first}-{last}) — {len(self.slots)} slot"
        return f"P{self.pattern_id} ({len(self.weeks)} tuần) — {len(self.slots)} slot"


# Constants cho pattern lẻ/chẵn — single source of truth.
PATTERN_BOTH = "both"             # Group xuất hiện cả tuần lẻ và chẵn
PATTERN_LE_ONLY = "le_only"       # Chỉ tuần lẻ
PATTERN_CHAN_ONLY = "chan_only"   # Chỉ tuần chẵn
PATTERN_NONE = "none"             # Không có data

# Severity levels cho health warnings — sort priority cao→thấp.
SEVERITY_ERROR = "error"
SEVERITY_WARNING = "warning"
SEVERITY_INFO = "info"
_SEVERITY_ORDER = {SEVERITY_ERROR: 0, SEVERITY_WARNING: 1, SEVERITY_INFO: 2}


# ---------------------------------------------------------------
# Trạng thái slot (cboTrangThai value mapping — verified từ web VnEdu)
# ---------------------------------------------------------------
# value="-1" --- (placeholder)
# value="0"  Bình thường   ← TKB chuẩn
# value="1"  Nghỉ          ← không tính PPCT
# value="2"  Dạy thay      ← tính PPCT (giáo viên dạy giúp)
# value="3"  Dạy bù        ← TIẾT BÙ (extra)
# value="4"  Chèn lịch     ← TIẾT BÙ (extra)
# value="5"  Dạy chung     ← tính PPCT
# value="6"  Phụ đạo       ← ngoài chương trình, không tính PPCT
# value="7"  Bồi dưỡng     ← ngoài chương trình
# value="8"  Dạy thêm      ← ngoài chương trình
TT_BINH_THUONG = "0"
TT_NGHI = "1"
TT_DAY_THAY = "2"
TT_DAY_BU = "3"
TT_CHEN_LICH = "4"
TT_DAY_CHUNG = "5"

# Các trạng thái có tính PPCT vào tiến độ chương trình
TT_COUNTED = frozenset({TT_BINH_THUONG, TT_DAY_THAY, TT_DAY_BU,
                        TT_CHEN_LICH, TT_DAY_CHUNG})
# Các trạng thái đánh dấu "tiết bù / chèn thêm" (ngoài TKB chuẩn)
TT_EXTRA = frozenset({TT_DAY_BU, TT_CHEN_LICH, TT_DAY_CHUNG})

# Loại sự kiện TKB do giáo viên tự đánh dấu trong hồ sơ.
TKB_EVENT_NGHI = "nghi"
TKB_EVENT_DAY_BU = "day_bu"
TKB_EVENT_LABELS = {
    TKB_EVENT_NGHI: "Nghỉ",
    TKB_EVENT_DAY_BU: "Dạy bù",
}


# ---------------------------------------------------------------
# Helpers nhận diện môn HĐTN — Hoạt động giáo dục theo chủ đề
# ---------------------------------------------------------------
# Dùng cho tính năng "Tự tính PPCT HĐTN Chủ đề" — nút trên wizard
# tính PPCT bắt đầu cho group HĐTN dựa vào tuan_from + số tiết/tuần
# (HĐTN-chủ đề: 1 tiết/tuần, có thể có lẻ/chẵn riêng).

def normalize_text_loose(text: str) -> str:
    """Lowercase + strip + bỏ dấu tiếng Việt cho match không phân biệt dấu."""
    if not text:
        return ""
    s = unicodedata.normalize("NFD", str(text))
    s = "".join(c for c in s if unicodedata.category(c) != "Mn")
    s = s.replace("đ", "d").replace("Đ", "d")
    return s.lower().strip()


def is_hdtn_mon(mon_text: str) -> bool:
    """Match môn HĐTN: 'Hoạt động trải nghiệm' / 'Hoạt động trải nghiệm, hướng nghiệp'."""
    n = normalize_text_loose(mon_text)
    return ("trai nghiem" in n) or ("hdtn" in n)


def is_hdtn_chu_de_phan_mon(phan_mon_text: str) -> bool:
    """Match phân môn 'Hoạt động giáo dục theo chủ đề'."""
    n = normalize_text_loose(phan_mon_text)
    return "chu de" in n


def is_hdtn_chu_de_group(mon_text: str, phan_mon_text: str) -> bool:
    """Group HĐTN-chủ-đề = môn HĐTN + phân môn 'theo chủ đề'."""
    return is_hdtn_mon(mon_text) and is_hdtn_chu_de_phan_mon(phan_mon_text)


def _compact_spaces(text: str) -> str:
    """Chuẩn hóa khoảng trắng nhưng giữ nguyên chữ tiếng Việt."""
    return " ".join(str(text or "").replace("\xa0", " ").split())


def _extract_grade_from_lop_text(lop_text: str) -> int | None:
    """Lấy khối từ tên lớp như 6A1/7A2. Không đoán khi thiếu dữ liệu."""
    m = re.search(r"\b([6-9])\s*[A-ZÀ-Ỹ]?", str(lop_text or ""), re.IGNORECASE)
    return int(m.group(1)) if m else None


def _classify_hdtn_part(mon_text: str, phan_mon_text: str) -> str:
    """Phân loại phân môn HĐTN dùng cho kho tên bài Word.

    Không được suy đoán chỉ từ tên môn "Hoạt động trải nghiệm". VnEdu có lúc
    render phân môn chậm/rỗng; nếu đoán mặc định là "Chủ đề" thì có thể ghi
    nhầm tên bài vào SHDC/SHL. Chỉ trả về khi text nói rõ phân môn.
    """
    combined = normalize_text_loose(f"{mon_text} {phan_mon_text}")
    if "sinh hoat lop" in combined or "shl" in combined:
        return "shl"
    if "sinh hoat duoi co" in combined or "chao co" in combined or "shdc" in combined:
        return "shdc"
    if "chu de" in combined or "giao duc theo" in combined or "hdgd" in combined:
        return "chu_de"
    return ""


def _ensure_sentence_period(text: str) -> str:
    """Thêm dấu chấm cuối câu cho tên bài SHDC nếu nguồn chưa có."""
    text = _compact_spaces(text)
    return text if not text or text[-1] in ".!?:;…" else f"{text}."


def _clean_hdtn_topic_text(text: str) -> str:
    """Sửa vài lỗi gõ rõ ràng trong nguồn Word trước khi ghi lên web."""
    s = _compact_spaces(text)
    replacements = {
        "lưa tuổi": "lứa tuổi",
        "Phát triển bề vững": "Phát triển bền vững",
        "người tốt việ tốt": "người tốt việc tốt",
    }
    for bad, good in replacements.items():
        s = s.replace(bad, good)
    return s


def _format_hdtn_topic_heading(text: str) -> str:
    """Chuẩn hóa tiêu đề chủ đề HĐTN trước khi làm tên bài."""
    s = _clean_hdtn_topic_text(text)
    s = re.sub(r"^CHỦ\s*ĐỀ\s*(\d+)\s*[\.:]?\s*", r"Chủ đề \1: ", s, flags=re.I)
    s = re.sub(r"^Chủ\s*đề\s*(\d+)\s*\.\s*", r"Chủ đề \1: ", s, flags=re.I)
    s = re.sub(r"^Chủ\s*đề\s*(\d+)\s*:\s*", r"Chủ đề \1: ", s, flags=re.I)
    s = re.sub(r"^(Chủ đề\s*\d+):\s*", lambda m: f"{m.group(1)}: ", s, flags=re.I)
    if ":" in s:
        prefix, rest = s.split(":", 1)
        rest = _compact_spaces(rest)
        letters = [ch for ch in rest if ch.isalpha()]
        if letters and sum(ch.isupper() for ch in letters) / max(len(letters), 1) > 0.7:
            rest = rest.lower()
            rest = rest[:1].upper() + rest[1:]
        s = f"{prefix.strip()}: {rest}".strip()
    return _compact_spaces(s)


@dataclass
class SubjectProgress:
    """Tiến độ PPCT của 1 (lop, mon, phan_mon) trên năm."""
    lop_id: str
    lop_text: str
    mon_id: str
    mon_text: str
    phan_mon_id: str
    phan_mon_text: str

    # Tiến độ hiện tại
    last_ppct: int = 0          # PPCT cuối cùng đã có
    last_ten_bai: str = ""      # Tên bài cuối cùng
    last_tuan: int = 0          # Tuần ghi PPCT cuối
    next_ppct: int = 1          # Đề xuất PPCT tiếp theo

    # Lịch sử
    ppct_history: list[tuple[int, int, str]] = field(default_factory=list)
    # list[(tuan, ppct, ten_bai)]

    # --- v2: Tracking tiết "extra" (dạy bù / chèn lịch / dạy chung) ---
    # Dùng để: (1) báo cáo cho user biết PPCT đã shift bao nhiêu vì có dạy bù,
    # (2) phát hiện sớm nếu PPCT next bị lệch do tool không quét lại web.
    extra_count: int = 0
    # list[(tuan, thu, buoi_idx, tiet_idx, ppct, trang_thai)]
    extras: list[tuple[int, int, int, int, int, str]] = field(default_factory=list)


@dataclass
class YearScanReport:
    """Tổng hợp scan toàn năm."""
    weeks_scanned: list[int] = field(default_factory=list)
    weeks_with_data: list[int] = field(default_factory=list)
    weeks_empty: list[int] = field(default_factory=list)
    patterns: list[YearTKBPattern] = field(default_factory=list)
    subject_progress: dict[str, SubjectProgress] = field(default_factory=dict)
    # key = "lop_id|mon_id|phan_mon_id"
    a_phan_mon_global: list[dict] = field(default_factory=list)


# ---------------------------------------------------------------
# Health scan structures — chỉ trong scope group user có quyền nhập
# ---------------------------------------------------------------

HEALTH_KIND_PPCT_GAP = "ppct_gap"
HEALTH_KIND_PPCT_DUPLICATE = "ppct_duplicate"
HEALTH_KIND_SLOT_MISSING = "slot_missing"
HEALTH_KIND_SLOT_EXTRA = "slot_extra"
HEALTH_KIND_GROUP_NO_DATA = "group_no_data"


@dataclass
class HealthIssue:
    """1 issue trong health report cho 1 group cụ thể.

    severity:
      - ok     : không có issue (chỉ dùng khi user bật show all)
      - warn   : issue nhẹ
      - error  : issue nặng
    """
    kind: str
    severity: str
    group_key: str
    lop_id: str
    lop_text: str
    mon_id: str
    mon_text: str
    phan_mon_id: str
    phan_mon_text: str
    week_from: int = 0
    week_to: int = 0
    ppct_from: int = 0
    ppct_to: int = 0
    missing_ppcts: list[int] = field(default_factory=list)
    duplicate_ppct: int = 0
    expected_slots: int = 0
    actual_slots: int = 0
    message: str = ""


@dataclass
class HealthScanResult:
    """Kết quả quét tình trạng KHDH trong scope allowed_groups."""
    allowed_groups: set[str] = field(default_factory=set)
    scanned_weeks: list[int] = field(default_factory=list)
    issues: list[HealthIssue] = field(default_factory=list)
    weeks_data: dict[int, "WeekData"] = field(default_factory=dict)
    actual_groups_seen: set[str] = field(default_factory=set)
    total_slots_scanned: int = 0

    @property
    def total_issue_count(self) -> int:
        return len([x for x in self.issues if x.severity != "ok"])

    @property
    def total_missing_ppcts(self) -> int:
        total = 0
        for issue in self.issues:
            total += len(issue.missing_ppcts or [])
        return total


# ---------------------------------------------------------------
# Analyzer
# ---------------------------------------------------------------

class PatternAnalyzer:
    """Static analyzer — không giữ state."""

    @staticmethod
    def cluster_patterns(weeks_data: dict[int, WeekData]) -> list[YearTKBPattern]:
        """Cluster các tuần có cùng TKB pattern.

        Pattern = set các (thu, buoi, tiet, lop_id, mon_id) có lop ≠ ''/0.
        Bỏ qua tên bài, PPCT, phan_mon — chỉ so cấu trúc TKB.
        """
        sig_to_weeks: dict[frozenset[_SlotKey], list[int]] = defaultdict(list)
        for tuan, wd in weeks_data.items():
            sig = frozenset(
                _SlotKey(s.thu, s.buoi_idx, s.tiet_idx, s.lop_id, s.mon_id or s.mon_dmonid)
                for s in wd.slots
                if s.has_lop
            )
            sig_to_weeks[sig].append(tuan)
        patterns = []
        for i, (sig, weeks) in enumerate(sorted(sig_to_weeks.items(), key=lambda x: -len(x[1])), 1):
            patterns.append(YearTKBPattern(
                pattern_id=i,
                weeks=sorted(weeks),
                slots=sorted(sig, key=lambda k: (k.thu, k.buoi_idx, k.tiet_idx)),
            ))
        return patterns

    @staticmethod
    def compute_progress(weeks_data: dict[int, WeekData]) -> dict[str, SubjectProgress]:
        """Compute tiến độ PPCT theo (lop, mon, phan_mon).

        Duyệt từ tuần thấp → cao, ghi nhận PPCT cao nhất cho mỗi nhóm.
        Khi 2 slot cùng nhóm trong 1 tuần (3 lớp song song), chỉ cần lấy max.

        v2 (extras-aware):
          - Filter slot theo trang_thai: chỉ tính nếu trang_thai ∈ TT_COUNTED.
          - Slot rỗng/placeholder (trang_thai="") được tính như TT_BINH_THUONG
            để giữ backward-compat với data cũ chưa có cboTrangThai render.
          - Slot có trang_thai ∈ TT_EXTRA → tăng `extra_count` và lưu vào
            `extras` để executor/UI biết PPCT đã shift bao nhiêu vì có dạy bù.
        """
        progress: dict[str, SubjectProgress] = {}
        sorted_weeks = sorted(weeks_data.keys())
        for tuan in sorted_weeks:
            wd = weeks_data[tuan]
            for slot in wd.filled_slots:
                if not slot.lop_id or not slot.phan_mon_id:
                    continue
                # Skip slot không có ppct numeric hoặc ppct=0
                try:
                    ppct_int = int(slot.ppct)
                except (ValueError, TypeError):
                    continue
                if ppct_int <= 0:
                    continue

                # v2: Filter theo trạng thái — bỏ Nghỉ/Phụ đạo/Bồi dưỡng/Dạy thêm.
                # Slot không có trang_thai (display mode chưa render select) →
                # treat như "Bình thường" để không bỏ sót data cũ.
                tt = (slot.trang_thai or "").strip()
                if tt and tt not in TT_COUNTED:
                    continue

                key = f"{slot.lop_id}|{slot.mon_id}|{slot.phan_mon_id}"
                p = progress.get(key)
                if p is None:
                    p = SubjectProgress(
                        lop_id=slot.lop_id,
                        lop_text=slot.lop_text,
                        mon_id=slot.mon_id,
                        mon_text=slot.mon_text or "",
                        phan_mon_id=slot.phan_mon_id,
                        phan_mon_text=slot.phan_mon_text,
                    )
                    progress[key] = p
                else:
                    # Enrich nếu lần đầu thiếu
                    if not p.mon_text and slot.mon_text:
                        p.mon_text = slot.mon_text
                    if not p.phan_mon_text or p.phan_mon_text == p.phan_mon_id:
                        if slot.phan_mon_text and slot.phan_mon_text != slot.phan_mon_id:
                            p.phan_mon_text = slot.phan_mon_text

                p.ppct_history.append((tuan, ppct_int, slot.ten_bai))
                if ppct_int > p.last_ppct:
                    p.last_ppct = ppct_int
                    p.last_ten_bai = slot.ten_bai
                    p.last_tuan = tuan

                # v2: Track tiết "extra" (dạy bù / chèn lịch / dạy chung)
                if tt in TT_EXTRA:
                    p.extra_count += 1
                    p.extras.append((tuan, slot.thu, slot.buoi_idx,
                                    slot.tiet_idx, ppct_int, tt))

        # Compute next_ppct
        for p in progress.values():
            p.next_ppct = p.last_ppct + 1
            # Sort history by ppct
            p.ppct_history.sort(key=lambda x: (x[0], x[1]))
            # Sort extras by (tuan, thu, buoi, tiet)
            p.extras.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        return progress

    @staticmethod
    def build_report(weeks_data: dict[int, WeekData]) -> YearScanReport:
        """Build full scan report."""
        rpt = YearScanReport()
        rpt.weeks_scanned = sorted(weeks_data.keys())
        rpt.weeks_with_data = sorted([t for t, w in weeks_data.items() if w.filled_slots])
        rpt.weeks_empty = sorted([t for t, w in weeks_data.items() if not w.filled_slots])
        rpt.patterns = PatternAnalyzer.cluster_patterns(weeks_data)
        rpt.subject_progress = PatternAnalyzer.compute_progress(weeks_data)

        # Pull aPhanMon từ tuần đầu tiên (chung toàn trường)
        if weeks_data:
            for t in rpt.weeks_scanned:
                wd = weeks_data[t]
                if wd.a_phan_mon:
                    rpt.a_phan_mon_global = wd.a_phan_mon
                    break

        # Enrich mon_text + phan_mon_text từ aPhanMon
        if rpt.a_phan_mon_global:
            mon_text_map = {}
            phan_mon_text_map = {}
            for pm in rpt.a_phan_mon_global:
                mon_id = str(pm.get("mon_hoc_id", ""))
                ten_mon = pm.get("ten_mon", "")
                if mon_id and ten_mon and mon_id not in mon_text_map:
                    mon_text_map[mon_id] = ten_mon
                pm_id = str(pm.get("id", ""))
                pm_ten = pm.get("ten", "") or pm.get("sten", "")
                if pm_id and pm_ten and pm_id not in phan_mon_text_map:
                    phan_mon_text_map[pm_id] = pm_ten
            for p in rpt.subject_progress.values():
                if (not p.mon_text or p.mon_text == p.mon_id) and p.mon_id in mon_text_map:
                    p.mon_text = mon_text_map[p.mon_id]
                if (
                    not p.phan_mon_text
                    or p.phan_mon_text == p.phan_mon_id
                    or p.phan_mon_text.isdigit()
                ) and p.phan_mon_id in phan_mon_text_map:
                    p.phan_mon_text = phan_mon_text_map[p.phan_mon_id]
        return rpt

    @staticmethod
    def find_pattern_for_week(report: YearScanReport, tuan: int) -> YearTKBPattern | None:
        for p in report.patterns:
            if tuan in p.weeks:
                return p
        return None

    @staticmethod
    def detect_extra_slots(
        week_data: "WeekData",
        tkb_template_keys: set[tuple[int, int, int, str, str]] | None = None,
    ) -> dict[str, list[dict]]:
        """Phát hiện slot "extra" (tiết bù / chèn lịch / dạy chung) trong 1 tuần.

        Logic 2 tầng:
          1. Primary: slot có `trang_thai` ∈ TT_EXTRA → là extra (cao confidence).
          2. Heuristic: slot có lop+mon+pm + trang_thai ∈ {"", "0"} (Bình thường)
             NHƯNG (thu, buoi, tiet, lop_id, mon_id) không thuộc tkb_template_keys
             → cũng là extra (user chưa khai trạng thái Dạy bù đúng).

        Args:
            week_data: WeekData của 1 tuần.
            tkb_template_keys: set các tuple (thu, buoi, tiet, lop_id, mon_id)
                định nghĩa TKB chuẩn của tuần này (lấy từ TKBPattern.slots
                hoặc KHDHProfile.get_active_template). Nếu None → chỉ dùng tầng 1.

        Returns:
            dict[group_key, list[extra_info]]:
              group_key = "lop_id|mon_id|phan_mon_id"
              extra_info = {
                "thu": int, "buoi": int, "tiet": int,
                "ppct": int, "trang_thai": str, "ten_bai": str,
                "source": "trang_thai" | "heuristic"
              }
        """
        result: dict[str, list[dict]] = {}
        for slot in week_data.filled_slots:
            if not slot.lop_id or not slot.phan_mon_id:
                continue
            try:
                ppct_int = int(slot.ppct)
            except (ValueError, TypeError):
                continue
            if ppct_int <= 0:
                continue

            tt = (slot.trang_thai or "").strip()
            # Skip slot không tính PPCT (Nghỉ/Phụ đạo/Bồi dưỡng/Dạy thêm)
            if tt and tt not in TT_COUNTED:
                continue

            is_extra = False
            source = ""
            if tt in TT_EXTRA:
                is_extra = True
                source = "trang_thai"
            elif tkb_template_keys is not None and tt in ("", TT_BINH_THUONG):
                # Heuristic: slot có data nhưng không khớp TKB template
                key = (slot.thu, slot.buoi_idx, slot.tiet_idx,
                       slot.lop_id, slot.mon_id or slot.mon_dmonid)
                if key not in tkb_template_keys:
                    is_extra = True
                    source = "heuristic"

            if not is_extra:
                continue

            group_key = f"{slot.lop_id}|{slot.mon_id}|{slot.phan_mon_id}"
            result.setdefault(group_key, []).append({
                "thu": slot.thu,
                "buoi": slot.buoi_idx,
                "tiet": slot.tiet_idx,
                "ppct": ppct_int,
                "trang_thai": tt,
                "ten_bai": slot.ten_bai,
                "source": source,
            })
        return result

    @staticmethod
    def compute_subject_breakdown(
        weeks_data: dict[int, "WeekData"],
        progress: dict[str, "SubjectProgress"] | None = None,
    ) -> dict[str, dict]:
        """Tính breakdown theo lẻ/chẵn + gap PPCT cho mỗi nhóm.

        Args:
            weeks_data: dict {tuan: WeekData} đã parse.
            progress: KHÔNG cần thiết cho logic — kept for backward compat.
                Caller có thể pass `None` hoặc bỏ qua.

        Trả dict[group_key] = {
            "le_ppcts": sorted list[int],     # PPCT xuất hiện ở tuần lẻ
            "chan_ppcts": sorted list[int],   # PPCT xuất hiện ở tuần chẵn
            "le_weeks": list[int],            # Tuần lẻ có dữ liệu
            "chan_weeks": list[int],          # Tuần chẵn có dữ liệu
            "pattern": "le_only" | "chan_only" | "both" | "none",
            "gaps": list[int],                # Các PPCT thiếu trong dãy 1..max
        }

        Lưu ý: PPCT là tuyến tính theo môn (server đếm cộng dồn không phân
        biệt lẻ/chẵn). Breakdown này chỉ để báo cáo cho user xem rõ pattern.
        """
        del progress  # marked as dead — function chỉ cần weeks_data
        out: dict[str, dict] = {}
        for tuan, wd in weeks_data.items():
            is_chan = KHDHProfile.is_chan(int(tuan))
            for slot in wd.filled_slots:
                if not slot.lop_id or not slot.phan_mon_id:
                    continue
                try:
                    ppct = int(slot.ppct)
                except (ValueError, TypeError):
                    continue
                if ppct <= 0:
                    continue
                key = f"{slot.lop_id}|{slot.mon_id}|{slot.phan_mon_id}"
                bd = out.setdefault(key, {
                    "le_ppcts": set(), "chan_ppcts": set(),
                    "le_weeks": set(), "chan_weeks": set(),
                })
                if is_chan:
                    bd["chan_ppcts"].add(ppct)
                    bd["chan_weeks"].add(int(tuan))
                else:
                    bd["le_ppcts"].add(ppct)
                    bd["le_weeks"].add(int(tuan))
        # Convert sets → sorted lists + tính pattern + gap
        for key, bd in out.items():
            le_p = sorted(bd["le_ppcts"])
            chan_p = sorted(bd["chan_ppcts"])
            le_w = sorted(bd["le_weeks"])
            chan_w = sorted(bd["chan_weeks"])
            bd["le_ppcts"] = le_p
            bd["chan_ppcts"] = chan_p
            bd["le_weeks"] = le_w
            bd["chan_weeks"] = chan_w
            if le_p and chan_p:
                bd["pattern"] = PATTERN_BOTH
            elif le_p and not chan_p:
                bd["pattern"] = PATTERN_LE_ONLY
            elif chan_p and not le_p:
                bd["pattern"] = PATTERN_CHAN_ONLY
            else:
                bd["pattern"] = PATTERN_NONE
            # Tính gap = các PPCT thiếu trong dãy 1..max
            all_p = sorted(set(le_p) | set(chan_p))
            if all_p:
                full = set(range(1, max(all_p) + 1))
                gaps = sorted(full - set(all_p))
                bd["gaps"] = gaps
            else:
                bd["gaps"] = []
        return out

    @staticmethod
    def compute_health_warnings(
        weeks_data: dict[int, "WeekData"],
        report: "YearScanReport",
        profile=None,
        breakdown: dict[str, dict] | None = None,
    ) -> list[dict]:
        """Phân tích sức khỏe data web — phát hiện vấn đề tiềm ẩn.

        Args:
            weeks_data: dict {tuan: WeekData}.
            report: YearScanReport đã build.
            profile: KHDHProfile (tùy chọn) — để so sánh missing/orphan.
            breakdown: kết quả của `compute_subject_breakdown` nếu caller đã
                tính sẵn — tránh tính lại lần 2 (perf optimization).

        Trả list[dict]:
            {type, severity: "info"|"warning"|"error", title, message, details}

        Các loại cảnh báo:
        1. weeks_missing — Tuần giữa năm không có data (gap ở weeks_with_data)
        2. ppct_gap — Group có PPCT bị thiếu ở giữa
        3. pattern_inconsistent — Pattern lẻ/chẵn xen kẽ bất thường
        4. group_orphan_in_profile — Group trên web không có trong profile
        5. group_missing_on_web — Group trong profile không thấy trên web
        6. ppct_duplicate — Cùng group có 2+ slot cùng PPCT trong 1 tuần (lỗi)
        """
        warnings: list[dict] = []

        # 1. Tuần giữa năm không có data
        scanned = sorted(report.weeks_scanned or [])
        with_data = set(report.weeks_with_data or [])
        if scanned and with_data:
            min_w_data = min(with_data)
            max_w_data = max(with_data)
            missing = [
                t for t in range(min_w_data, max_w_data + 1)
                if t in set(scanned) and t not in with_data
            ]
            if missing:
                warnings.append({
                    "type": "weeks_missing",
                    "severity": SEVERITY_WARNING,
                    "title": f"Có {len(missing)} tuần giữa năm bị trống",
                    "message": (
                        f"Các tuần {missing[:8]}{'…' if len(missing) > 8 else ''} "
                        "nằm giữa các tuần có dữ liệu nhưng web không có slot nào. "
                        "Có thể bạn chưa nhập, hoặc data đã bị xóa."
                    ),
                    "details": {"weeks": missing},
                })

        # 2. PPCT gap — reuse breakdown nếu caller đã tính, tránh O(n²)
        if breakdown is None:
            breakdown = PatternAnalyzer.compute_subject_breakdown(weeks_data)
        groups_with_gaps = []
        for key, bd in breakdown.items():
            if bd["gaps"]:
                p = report.subject_progress.get(key)
                if p:
                    groups_with_gaps.append({
                        "key": key,
                        "label": f"{p.lop_text or p.lop_id} / {p.phan_mon_text or p.phan_mon_id}",
                        "gaps": bd["gaps"],
                        "max_ppct": p.last_ppct,
                    })
        if groups_with_gaps:
            for g in groups_with_gaps[:10]:
                gaps_text = ", ".join(str(x) for x in g["gaps"][:8])
                if len(g["gaps"]) > 8:
                    gaps_text += f" … (+{len(g['gaps']) - 8})"
                warnings.append({
                    "type": "ppct_gap",
                    "severity": SEVERITY_WARNING,
                    "title": f"Thiếu PPCT: {g['label']}",
                    "message": (
                        f"Web đã có PPCT đến {g['max_ppct']} cho nhóm này, "
                        f"nhưng thiếu các tiết: {gaps_text}. "
                        "Có thể do bạn nhập không liên tục."
                    ),
                    "details": g,
                })

        # 3. Pattern lẻ/chẵn — group "le_only" hoặc "chan_only" mà số tuần
        #    đáng kể (≥3) → đáng chú ý vì có thể user dạy đặc thù lẻ/chẵn
        for key, bd in breakdown.items():
            if bd["pattern"] in (PATTERN_LE_ONLY, PATTERN_CHAN_ONLY):
                # Chỉ báo nếu có ≥3 tuần (tránh noise)
                weeks_count = (
                    len(bd["le_weeks"]) if bd["pattern"] == PATTERN_LE_ONLY
                    else len(bd["chan_weeks"])
                )
                if weeks_count >= 3:
                    p = report.subject_progress.get(key)
                    if p:
                        warnings.append({
                            "type": "pattern_le_chan",
                            "severity": SEVERITY_INFO,
                            "title": (
                                f"Chỉ tuần {'lẻ' if bd['pattern'] == PATTERN_LE_ONLY else 'chẵn'}: "
                                f"{p.lop_text or p.lop_id} / {p.phan_mon_text or p.phan_mon_id}"
                            ),
                            "message": (
                                f"Nhóm này chỉ xuất hiện ở tuần "
                                f"{'lẻ' if bd['pattern'] == PATTERN_LE_ONLY else 'chẵn'} "
                                f"({weeks_count} tuần). Đảm bảo profile của "
                                "bạn cũng đặt slot này đúng tuần lẻ/chẵn."
                            ),
                            "details": {"key": key, "pattern": bd["pattern"]},
                        })

        # 4 + 5. So sánh với profile (nếu có)
        if profile is not None:
            profile_keys = set()
            for entry in (profile.ppct_starts or []):
                profile_keys.add(entry.group_key)
            web_keys = set(report.subject_progress.keys())

            # Web có nhưng profile không có
            orphan_in_profile = web_keys - profile_keys
            if orphan_in_profile:
                names = []
                for k in list(orphan_in_profile)[:5]:
                    p = report.subject_progress.get(k)
                    if p:
                        names.append(
                            f"{p.lop_text or p.lop_id}/{p.phan_mon_text or p.phan_mon_id}"
                        )
                warnings.append({
                    "type": "group_orphan_in_profile",
                    "severity": SEVERITY_WARNING,
                    "title": f"{len(orphan_in_profile)} nhóm web không có trong profile",
                    "message": (
                        f"Web có data cho: {'; '.join(names)}"
                        + (f" và {len(orphan_in_profile) - 5} nhóm khác"
                           if len(orphan_in_profile) > 5 else "")
                        + ". Có thể bạn đã bỏ khỏi profile nhưng web còn data cũ."
                    ),
                    "details": {"keys": list(orphan_in_profile)},
                })

            # Profile có nhưng web không có
            missing_on_web = profile_keys - web_keys
            if missing_on_web:
                names = []
                for k in list(missing_on_web)[:5]:
                    for entry in profile.ppct_starts:
                        if entry.group_key == k:
                            names.append(
                                f"{entry.lop_text}/{entry.phan_mon_text}"
                            )
                            break
                warnings.append({
                    "type": "group_missing_on_web",
                    "severity": SEVERITY_INFO,
                    "title": f"{len(missing_on_web)} nhóm profile chưa có data web",
                    "message": (
                        f"Profile của bạn có: {'; '.join(names)}"
                        + (f" và {len(missing_on_web) - 5} nhóm khác"
                           if len(missing_on_web) > 5 else "")
                        + ". Các nhóm này chưa từng được nhập trên web."
                    ),
                    "details": {"keys": list(missing_on_web)},
                })

        # 6. PPCT duplicate trong 1 tuần
        for tuan, wd in weeks_data.items():
            seen: dict[str, list[int]] = {}
            for slot in wd.filled_slots:
                if not slot.lop_id or not slot.phan_mon_id:
                    continue
                try:
                    ppct = int(slot.ppct)
                except (ValueError, TypeError):
                    continue
                if ppct <= 0:
                    continue
                key = f"{slot.lop_id}|{slot.mon_id}|{slot.phan_mon_id}"
                seen.setdefault(key, []).append(ppct)
            for key, ppcts in seen.items():
                if len(ppcts) != len(set(ppcts)):
                    p = report.subject_progress.get(key)
                    if p:
                        # Tìm các PPCT bị duplicate
                        counts = Counter(ppcts)
                        dups = sorted([
                            ppct for ppct, c in counts.items() if c > 1
                        ])
                        warnings.append({
                            "type": "ppct_duplicate",
                            "severity": SEVERITY_ERROR,
                            "title": (
                                f"PPCT trùng tại tuần {tuan}: "
                                f"{p.lop_text or p.lop_id} / "
                                f"{p.phan_mon_text or p.phan_mon_id}"
                            ),
                            "message": (
                                f"Có nhiều slot cùng PPCT {dups} trong 1 tuần. "
                                "Server thường reject save trong tình huống này."
                            ),
                            "details": {"key": key, "tuan": tuan, "dups": dups},
                        })

        # Sort warnings theo severity (error > warning > info)
        warnings.sort(
            key=lambda w: (
                _SEVERITY_ORDER.get(w.get("severity"), 9),
                w.get("title", ""),
            )
        )
        return warnings

    @staticmethod
    def analyze_health_in_scope(
        weeks_data: dict[int, "WeekData"],
        allowed_groups: set[str],
        expected_slot_count_by_week: dict[int, dict[str, int]] | None = None,
    ) -> HealthScanResult:
        """Quét tình trạng KHDH chỉ trong scope group user có quyền nhập.

        Scope = group_key xuất hiện trong profile/template hiện tại.

        Detect 4 loại issue:
          - PPCT gap
          - PPCT duplicate
          - Slot thiếu so với template active của tuần
          - Slot thừa so với template active của tuần
        """
        result = HealthScanResult(
            allowed_groups=set(allowed_groups or set()),
            scanned_weeks=sorted(weeks_data.keys()),
            weeks_data=weeks_data,
        )
        if not result.allowed_groups or not weeks_data:
            return result

        # group_key -> list[(tuan, thu, buoi, tiet, ppct, ten_bai)]
        history: dict[str, list[tuple[int, int, int, int, int, str]]] = defaultdict(list)
        # week -> group -> slot_count
        actual_slot_count_by_week: dict[int, dict[str, int]] = defaultdict(lambda: defaultdict(int))

        for tuan, wd in weeks_data.items():
            for slot in wd.filled_slots:
                if not slot.lop_id or not slot.phan_mon_id:
                    continue
                group_key = f"{slot.lop_id}|{(slot.mon_id or slot.mon_dmonid)}|{slot.phan_mon_id}"
                if group_key not in result.allowed_groups:
                    continue
                try:
                    ppct = int(slot.ppct)
                except (ValueError, TypeError):
                    continue
                if ppct <= 0:
                    continue
                result.actual_groups_seen.add(group_key)
                result.total_slots_scanned += 1
                history[group_key].append(
                    (tuan, slot.thu, slot.buoi_idx, slot.tiet_idx, ppct, slot.ten_bai)
                )
                actual_slot_count_by_week[tuan][group_key] += 1

        # 0. Group trong scope nhưng hoàn toàn không có data trên web
        no_data_groups = sorted(result.allowed_groups - result.actual_groups_seen)
        for group_key in no_data_groups:
            lop_id, mon_id, phan_mon_id = group_key.split("|", 2)
            result.issues.append(HealthIssue(
                kind=HEALTH_KIND_GROUP_NO_DATA,
                severity="warn",
                group_key=group_key,
                lop_id=lop_id,
                lop_text=lop_id,
                mon_id=mon_id,
                mon_text=mon_id,
                phan_mon_id=phan_mon_id,
                phan_mon_text=phan_mon_id,
                message="Không thấy bất kỳ dữ liệu nào trên web cho group này trong dải tuần đã quét.",
            ))

        # 1. PPCT gap + duplicate per group
        for group_key, items in history.items():
            if not items:
                continue
            items_sorted = sorted(items, key=lambda x: (x[0], x[1], x[2], x[3], x[4]))
            sample = items_sorted[0]
            lop_id, mon_id, phan_mon_id = group_key.split("|", 2)

            # Resolve display labels from any matching slot in history
            lop_text = lop_id
            mon_text = mon_id
            phan_mon_text = phan_mon_id
            found_labels = False
            for tuan, wd in weeks_data.items():
                for slot in wd.filled_slots:
                    gk = f"{slot.lop_id}|{slot.mon_id}|{slot.phan_mon_id}"
                    if gk == group_key:
                        lop_text = slot.lop_text or lop_id
                        mon_text = slot.mon_text or mon_id
                        phan_mon_text = slot.phan_mon_text or phan_mon_id
                        found_labels = True
                        break
                if found_labels:
                    break

            # duplicate check: same ppct appears more than once in scope history
            ppct_counts = Counter(ppct for _, _, _, _, ppct, _ in items_sorted)
            for dup_ppct, count in ppct_counts.items():
                if count > 1:
                    dup_weeks = sorted({t for t, _, _, _, p, _ in items_sorted if p == dup_ppct})
                    result.issues.append(HealthIssue(
                        kind=HEALTH_KIND_PPCT_DUPLICATE,
                        severity="error",
                        group_key=group_key,
                        lop_id=lop_id,
                        lop_text=lop_text,
                        mon_id=mon_id,
                        mon_text=mon_text,
                        phan_mon_id=phan_mon_id,
                        phan_mon_text=phan_mon_text,
                        week_from=min(dup_weeks),
                        week_to=max(dup_weeks),
                        duplicate_ppct=dup_ppct,
                        message=f"PPCT {dup_ppct} bị trùng {count} lần trong scope đã quét.",
                    ))

            prev_ppct = None
            prev_tuan = 0
            for tuan, thu, buoi, tiet, ppct, _ in items_sorted:
                if prev_ppct is None:
                    prev_ppct = ppct
                    prev_tuan = tuan
                    continue
                if ppct > prev_ppct + 1:
                    missing = list(range(prev_ppct + 1, ppct))
                    sev = "warn" if len(missing) <= 2 else "error"
                    result.issues.append(HealthIssue(
                        kind=HEALTH_KIND_PPCT_GAP,
                        severity=sev,
                        group_key=group_key,
                        lop_id=lop_id,
                        lop_text=lop_text,
                        mon_id=mon_id,
                        mon_text=mon_text,
                        phan_mon_id=phan_mon_id,
                        phan_mon_text=phan_mon_text,
                        week_from=prev_tuan,
                        week_to=tuan,
                        ppct_from=prev_ppct,
                        ppct_to=ppct,
                        missing_ppcts=missing,
                        message=(
                            f"PPCT nhảy từ {prev_ppct} → {ppct}, thiếu {missing}."
                        ),
                    ))
                prev_ppct = max(prev_ppct, ppct)
                prev_tuan = tuan

        # 2. Slot thiếu/thừa theo template active của tuần
        if expected_slot_count_by_week:
            all_weeks = sorted(expected_slot_count_by_week.keys())
            for tuan in all_weeks:
                expected_map = expected_slot_count_by_week.get(tuan, {})
                actual_map = actual_slot_count_by_week.get(tuan, {})
                for group_key, expected_count in expected_map.items():
                    if group_key not in result.allowed_groups:
                        continue
                    actual_count = int(actual_map.get(group_key, 0))
                    if actual_count == expected_count:
                        continue
                    lop_id, mon_id, phan_mon_id = group_key.split("|", 2)
                    # best effort labels
                    lop_text = lop_id
                    mon_text = mon_id
                    phan_mon_text = phan_mon_id
                    for wd in weeks_data.values():
                        for slot in wd.filled_slots:
                            if f"{slot.lop_id}|{slot.mon_id}|{slot.phan_mon_id}" == group_key:
                                lop_text = slot.lop_text or lop_id
                                mon_text = slot.mon_text or mon_id
                                phan_mon_text = slot.phan_mon_text or phan_mon_id
                                break
                        else:
                            continue
                        break

                    if actual_count < expected_count:
                        result.issues.append(HealthIssue(
                            kind=HEALTH_KIND_SLOT_MISSING,
                            severity="warn",
                            group_key=group_key,
                            lop_id=lop_id,
                            lop_text=lop_text,
                            mon_id=mon_id,
                            mon_text=mon_text,
                            phan_mon_id=phan_mon_id,
                            phan_mon_text=phan_mon_text,
                            week_from=tuan,
                            week_to=tuan,
                            expected_slots=expected_count,
                            actual_slots=actual_count,
                            message=f"Thiếu {expected_count - actual_count} slot so với template tuần {tuan}.",
                        ))
                    else:
                        result.issues.append(HealthIssue(
                            kind=HEALTH_KIND_SLOT_EXTRA,
                            severity="warn",
                            group_key=group_key,
                            lop_id=lop_id,
                            lop_text=lop_text,
                            mon_id=mon_id,
                            mon_text=mon_text,
                            phan_mon_id=phan_mon_id,
                            phan_mon_text=phan_mon_text,
                            week_from=tuan,
                            week_to=tuan,
                            expected_slots=expected_count,
                            actual_slots=actual_count,
                            message=f"Thừa {actual_count - expected_count} slot so với template tuần {tuan}.",
                        ))

        result.issues.sort(
            key=lambda x: (
                {"error": 0, "warn": 1, "ok": 2}.get(x.severity, 9),
                x.lop_text,
                x.mon_text,
                x.phan_mon_text,
                x.week_from,
                x.ppct_from,
            )
        )
        return result


# ######################################################################
# Section: catalog
# ######################################################################





@dataclass
class LessonEntry:
    """1 entry: (lop, mon, phan_mon, ppct) → ten_bai."""
    lop_id: str
    mon_id: str
    phan_mon_id: str
    ppct: int
    ten_bai: str
    source: str = "filled"  # "filled" | "log" | "user"
    seen_in_weeks: list[int] = field(default_factory=list)
    # Display labels (denormalized) — tiện cho UI khỏi phải lookup từ report mỗi lần
    lop_text: str = ""
    mon_text: str = ""
    phan_mon_text: str = ""

    def key(self) -> tuple[str, str, str, int]:
        return (self.lop_id, self.mon_id, self.phan_mon_id, self.ppct)


# Priority khi merge từ nhiều nguồn
_SOURCE_PRIORITY = {"user": 3, "filled": 2, "log": 1}


class LessonCatalog:
    """Catalog tên bài.

    Sử dụng:
        cat = LessonCatalog()
        cat.ingest_weeks(weeks_data)
        cat.ingest_log(log_records)
        ten_bai = cat.lookup(lop_id, mon_id, pm_id, ppct=103)
    """

    def __init__(self):
        self._entries: dict[tuple, LessonEntry] = {}

    # -----------------------------------------------------------
    # INGEST
    # -----------------------------------------------------------

    def ingest_weeks(self, weeks: dict[int, WeekData]) -> int:
        """Ingest từ filled slots. Trả số entry mới."""
        added = 0
        for tuan in sorted(weeks.keys()):
            wd = weeks[tuan]
            for slot in wd.filled_slots:
                if not slot.lop_id or not slot.phan_mon_id or not slot.ten_bai:
                    continue
                try:
                    ppct = int(slot.ppct)
                except (ValueError, TypeError):
                    continue
                if ppct <= 0:
                    continue
                entry = LessonEntry(
                    lop_id=slot.lop_id,
                    mon_id=slot.mon_id,
                    phan_mon_id=slot.phan_mon_id,
                    ppct=ppct,
                    ten_bai=slot.ten_bai.strip(),
                    source="filled",
                    seen_in_weeks=[tuan],
                    lop_text=slot.lop_text or "",
                    mon_text=slot.mon_text or "",
                    phan_mon_text=slot.phan_mon_text or "",
                )
                if self._upsert(entry):
                    added += 1
        return added

    def ingest_log(self, log_records: Iterable[dict]) -> int:
        """Ingest từ log delete records (response của getLichBaoGiangLog).

        Mỗi record có: lop_hoc_id, mon_hoc_id, phan_mon_id, tiet_ppct, ten_bai_day, tuan
        """
        added = 0
        for rec in log_records:
            lop_id = str(rec.get("lop_hoc_id", "") or "")
            mon_id = str(rec.get("mon_hoc_id", "") or "")
            pm_id = str(rec.get("phan_mon_id", "") or "")
            ten_bai = str(rec.get("ten_bai_day", "") or "").strip()
            try:
                ppct = int(rec.get("tiet_ppct", 0) or 0)
            except (ValueError, TypeError):
                continue
            if not (lop_id and pm_id and ten_bai and ppct > 0):
                continue
            tuan = int(rec.get("tuan", 0) or 0) or None
            entry = LessonEntry(
                lop_id=lop_id, mon_id=mon_id, phan_mon_id=pm_id,
                ppct=ppct, ten_bai=ten_bai, source="log",
                seen_in_weeks=[tuan] if tuan else [],
            )
            if self._upsert(entry):
                added += 1
        return added

    def add_user_entry(self, lop_id: str, mon_id: str, phan_mon_id: str,
                       ppct: int, ten_bai: str) -> bool:
        """Override 1 entry với source 'user'."""
        entry = LessonEntry(
            lop_id=lop_id, mon_id=mon_id, phan_mon_id=phan_mon_id,
            ppct=int(ppct), ten_bai=str(ten_bai).strip(), source="user",
        )
        return self._upsert(entry)

    def _upsert(self, new: LessonEntry) -> bool:
        """Insert hoặc update theo source priority. Trả True nếu thay đổi."""
        key = new.key()
        existing = self._entries.get(key)
        if existing is None:
            self._entries[key] = new
            return True
        # Conflict: chọn source ưu tiên cao hơn
        new_pri = _SOURCE_PRIORITY.get(new.source, 0)
        ex_pri = _SOURCE_PRIORITY.get(existing.source, 0)
        if new_pri > ex_pri:
            new.seen_in_weeks = list(set(existing.seen_in_weeks + new.seen_in_weeks))
            # Carry-over labels nếu new bị thiếu
            new.lop_text = new.lop_text or existing.lop_text
            new.mon_text = new.mon_text or existing.mon_text
            new.phan_mon_text = new.phan_mon_text or existing.phan_mon_text
            self._entries[key] = new
            return True
        if new_pri == ex_pri:
            # Cùng source, merge weeks + enrich labels
            merged = list(set(existing.seen_in_weeks + new.seen_in_weeks))
            existing.seen_in_weeks = sorted([w for w in merged if w])
            if not existing.lop_text and new.lop_text:
                existing.lop_text = new.lop_text
            if not existing.mon_text and new.mon_text:
                existing.mon_text = new.mon_text
            if not existing.phan_mon_text and new.phan_mon_text:
                existing.phan_mon_text = new.phan_mon_text
            return False
        return False

    # -----------------------------------------------------------
    # LOOKUP
    # -----------------------------------------------------------

    def lookup(self, lop_id: str, mon_id: str, phan_mon_id: str, ppct: int) -> str | None:
        """Tìm tên bài cho 1 (lop, mon, pm, ppct). Trả None nếu không có."""
        key = (str(lop_id), str(mon_id), str(phan_mon_id), int(ppct))
        e = self._entries.get(key)
        return e.ten_bai if e else None

    def lookup_with_fallback(self, lop_id: str, mon_id: str, phan_mon_id: str, ppct: int) -> str | None:
        """Tìm với fallback: nếu (lop, mon, pm, ppct) không có thì thử các lớp khác cùng (mon, pm, ppct)."""
        direct = self.lookup(lop_id, mon_id, phan_mon_id, ppct)
        if direct:
            return direct
        # Fallback: cùng phan_mon + ppct, lớp khác (giả định khối tương tự)
        for k, e in self._entries.items():
            l, m, p, c = k
            if m == str(mon_id) and p == str(phan_mon_id) and c == int(ppct):
                return e.ten_bai
        return None

    def list_by_subject(self, lop_id: str, mon_id: str, phan_mon_id: str) -> list[LessonEntry]:
        """Trả list entry đã sort theo PPCT."""
        out = [e for k, e in self._entries.items()
              if k[0] == str(lop_id) and k[1] == str(mon_id) and k[2] == str(phan_mon_id)]
        return sorted(out, key=lambda e: e.ppct)

    def all_entries(self) -> list[LessonEntry]:
        return list(self._entries.values())

    # -----------------------------------------------------------
    # PERSIST
    # -----------------------------------------------------------

    def to_dict(self) -> dict:
        return {
            "version": 1,
            "entries": [
                {
                    "lop_id": e.lop_id, "mon_id": e.mon_id, "phan_mon_id": e.phan_mon_id,
                    "ppct": e.ppct, "ten_bai": e.ten_bai, "source": e.source,
                    "seen_in_weeks": e.seen_in_weeks,
                }
                for e in self._entries.values()
            ],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "LessonCatalog":
        cat = cls()
        for e in (data.get("entries") or []):
            entry = LessonEntry(
                lop_id=str(e.get("lop_id", "")),
                mon_id=str(e.get("mon_id", "")),
                phan_mon_id=str(e.get("phan_mon_id", "")),
                ppct=int(e.get("ppct", 0)),
                ten_bai=str(e.get("ten_bai", "")),
                source=str(e.get("source", "user")),
                seen_in_weeks=list(e.get("seen_in_weeks", [])),
            )
            cat._upsert(entry)
        return cat

    def save_json(self, path: str | Path) -> None:
        Path(path).write_text(json.dumps(self.to_dict(), ensure_ascii=False, indent=2),
                            encoding="utf-8")

    @classmethod
    def load_json(cls, path: str | Path) -> "LessonCatalog":
        return cls.from_dict(json.loads(Path(path).read_text(encoding="utf-8")))

    def export_csv(self, path: str | Path) -> None:
        with Path(path).open("w", encoding="utf-8-sig", newline="") as f:
            w = csv.writer(f)
            w.writerow(["lop_id", "mon_id", "phan_mon_id", "ppct", "ten_bai", "source", "seen_in_weeks"])
            for e in sorted(self._entries.values(), key=lambda x: (x.lop_id, x.phan_mon_id, x.ppct)):
                w.writerow([e.lop_id, e.mon_id, e.phan_mon_id, e.ppct, e.ten_bai,
                          e.source, "|".join(str(t) for t in e.seen_in_weeks)])

    def import_csv(self, path: str | Path) -> int:
        added = 0
        with Path(path).open("r", encoding="utf-8-sig") as f:
            reader = csv.DictReader(f)
            for row in reader:
                try:
                    e = LessonEntry(
                        lop_id=str(row.get("lop_id", "")),
                        mon_id=str(row.get("mon_id", "")),
                        phan_mon_id=str(row.get("phan_mon_id", "")),
                        ppct=int(row.get("ppct", 0)),
                        ten_bai=str(row.get("ten_bai", "")),
                        source=str(row.get("source", "user")) or "user",
                    )
                    if self._upsert(e):
                        added += 1
                except Exception:
                    continue
        return added

    def __len__(self) -> int:
        return len(self._entries)


@dataclass(frozen=True)
class HDTNLessonTitleEntry:
    """Một dòng tên bài HĐTN đọc từ kế hoạch Word."""
    ppct: int
    week: int
    topic: str
    topic_lesson: int
    detail: str = ""

    def short_title(self) -> str:
        return f"{self.topic} - Tiết {self.topic_lesson}"

    def compact_pair_title(self) -> str:
        return f"{self.topic} (tiết {self.topic_lesson})"


class HDTNLessonTitleCatalog:
    """Kho tên bài HĐTN dùng khi VnEdu không tự load tên bài."""

    DEFAULT_FILES = {
        "chu_de": Path("HĐTN") / "HDTN 6 CHỦ ĐỀ.docx",
        "shdc": Path("HĐTN") / "HDTN 6_25-26 - SHDC.docx",
        "shl": Path("HĐTN") / "HDTN 6_25-26 - SHL.docx",
    }
    GRADE8_CHU_DE_FILE = Path("HĐTN") / "25-26 PHỤ LỤC III HDTN 8.docx"

    def __init__(self, entries: dict[str, dict[int, list[HDTNLessonTitleEntry]]] | None = None):
        self._entries = entries or {
            "6:chu_de": {}, "6:shdc": {}, "6:shl": {},
            "8:chu_de": {},
        }
        self.load_errors: list[str] = []

    @classmethod
    def load_default(cls, base_dir: str | Path | None = None) -> "HDTNLessonTitleCatalog":
        """Đọc các file Word HĐTN cạnh tool, fail-soft nếu thiếu file."""
        base = Path(base_dir) if base_dir else Path(__file__).resolve().parent
        cat = cls()
        try:
            from docx import Document
        except Exception as e:
            cat.load_errors.append(f"Thiếu python-docx: {e}")
            return cat

        for kind, rel_path in cls.DEFAULT_FILES.items():
            path = base / rel_path
            if not path.exists():
                cat.load_errors.append(f"Không thấy file {path}")
                continue
            try:
                cat._read_word_table(kind, Document(str(path)), grade=6)
            except Exception as e:
                cat.load_errors.append(f"Không đọc được {path.name}: {e}")

        grade8_path = base / cls.GRADE8_CHU_DE_FILE
        if grade8_path.exists():
            try:
                cat._read_grade8_chu_de_word(Document(str(grade8_path)))
            except Exception as e:
                cat.load_errors.append(f"Không đọc được {grade8_path.name}: {e}")
        return cat

    @staticmethod
    def _catalog_key(grade: int, kind: str) -> str:
        return f"{int(grade)}:{kind}"

    def _read_word_table(self, kind: str, document, grade: int) -> None:
        if len(document.tables) < 2:
            self.load_errors.append(f"lớp {grade} {kind}: file Word không có bảng phân phối")
            return
        table = document.tables[1]
        current_topic = ""
        topic_lesson = 0
        catalog_key = self._catalog_key(grade, kind)
        for row in table.rows[1:]:
            cells = [_compact_spaces(c.text) for c in row.cells]
            if not cells:
                continue
            first = cells[0]
            second = cells[1] if len(cells) > 1 else ""
            if not re.fullmatch(r"\d+", first or ""):
                topic = _clean_hdtn_topic_text(first or second)
                if topic and not topic.startswith("..."):
                    current_topic = topic
                    topic_lesson = 0
                continue
            if not current_topic:
                continue
            ppct = int(first)
            topic_lesson += 1
            week = self._extract_week(cells[3] if len(cells) > 3 else "")
            entry = HDTNLessonTitleEntry(
                ppct=ppct,
                week=week,
                topic=current_topic,
                topic_lesson=topic_lesson,
                detail=_compact_spaces(second),
            )
            self._entries.setdefault(catalog_key, {}).setdefault(ppct, []).append(entry)

    def _read_grade8_chu_de_word(self, document) -> None:
        """Đọc HĐTN 8: mỗi tuần 3 tiết, dòng giữa là HĐGD theo chủ đề."""
        if len(document.tables) < 3:
            self.load_errors.append("lớp 8 chủ đề: file Word thiếu bảng học kỳ")
            return
        week_rows: dict[int, list[tuple[int, str, str]]] = defaultdict(list)
        current_topic = ""
        for table_index in (1, 2):
            table = document.tables[table_index]
            for row in table.rows[1:]:
                cells = [_compact_spaces(c.text) for c in row.cells]
                if len(cells) < 5:
                    continue
                week = self._extract_week(cells[0])
                word_lesson = self._extract_int_cell(cells[1])
                content = cells[4]
                if not week or not word_lesson:
                    if content and "CHỦ ĐỀ" in content.upper():
                        current_topic = _format_hdtn_topic_heading(content)
                    continue
                topic_from_content = self._extract_topic_from_grade8_content(content)
                if topic_from_content:
                    current_topic = topic_from_content
                week_rows.setdefault(week, []).append((word_lesson, content, current_topic))

        catalog_key = self._catalog_key(8, "chu_de")
        topic_counts: dict[str, int] = defaultdict(int)
        for ppct, week in enumerate(sorted(week_rows), start=1):
            rows = week_rows[week]
            if len(rows) < 2:
                self.load_errors.append(f"lớp 8 chủ đề: tuần {week} thiếu dòng giữa")
                continue
            word_lesson, content, topic = rows[1]
            if not topic:
                self.load_errors.append(f"lớp 8 chủ đề: tuần {week} không xác định được chủ đề")
                continue
            topic_counts[topic] += 1
            entry = HDTNLessonTitleEntry(
                ppct=ppct,
                week=week,
                topic=topic,
                topic_lesson=topic_counts[topic],
                detail=_compact_spaces(content),
            )
            self._entries.setdefault(catalog_key, {}).setdefault(ppct, []).append(entry)

    @staticmethod
    def _extract_week(text: str) -> int:
        m = re.search(r"\d+", str(text or ""))
        return int(m.group(0)) if m else 0

    @staticmethod
    def _extract_int_cell(text: str) -> int:
        s = _compact_spaces(text)
        return int(s) if re.fullmatch(r"\d+", s or "") else 0

    @staticmethod
    def _extract_topic_from_grade8_content(content: str) -> str:
        c = _compact_spaces(content)
        m = re.search(
            r"(Chủ\s*đề\s*\d+\s*[:\.]?\s*.*?)(?=\s*-\s*NV\d|\s+-NV\d|\s+NV\d|$)",
            c,
            flags=re.I,
        )
        return _format_hdtn_topic_heading(m.group(1).rstrip(" -.;")) if m else ""

    def lookup_for_op(self, op: "FillOp") -> str | None:
        """Tìm tên bài theo khối/phân môn/PPCT."""
        if not op or not op.ppct:
            return None
        grade = _extract_grade_from_lop_text(op.lop_text)
        if grade not in (6, 8):
            return None
        kind = _classify_hdtn_part(op.mon_text, op.phan_mon_text)
        if grade == 8 and kind != "chu_de":
            return None
        catalog_key = self._catalog_key(grade, kind)
        if catalog_key not in self._entries:
            return None
        matches = self._entries.get(catalog_key, {}).get(int(op.ppct), [])
        if not matches:
            return None
        if len(matches) > 1:
            return " - ".join(e.compact_pair_title() for e in matches)
        entry = matches[0]
        if kind == "shdc":
            title = f"{entry.short_title()}: {_compact_spaces(entry.detail)}"
            return _ensure_sentence_period(title)
        return entry.short_title()


_HDTN_TITLE_CATALOG_CACHE: HDTNLessonTitleCatalog | None = None


def get_hdtn_lesson_title_catalog() -> HDTNLessonTitleCatalog:
    """Cache kho tên bài HĐTN để mỗi phiên nhập không đọc Word lặp lại."""
    global _HDTN_TITLE_CATALOG_CACHE
    if _HDTN_TITLE_CATALOG_CACHE is None:
        _HDTN_TITLE_CATALOG_CACHE = HDTNLessonTitleCatalog.load_default()
    return _HDTN_TITLE_CATALOG_CACHE


