# Đọc context từ ExtJS components
_JS_GET_CONTEXT = r"""
() => {
    const out = {
        my_token: window.my_token || '',
        my_user_id: (window.phpviet_user && phpviet_user.id) || '',
        nam_hoc: window.phpviet_nam_hoc_v5 || window.phpviet_nam_hoc || 0,
        win_id: '',
        cap_hoc: 0,
        cap_hoc_text: '',
        giao_vien_id: 0,
        giao_vien_name: '',
        tuan_hoc: 0,
        ngay_tac_dung_tkb: '',
        site_id: (window.phpviet_user && phpviet_user.site_id) || '',
    };
    try {
        const wins = Ext.ComponentQuery.query('window').filter(w => /Kế hoạch dạy học/.test(w.title || ''));
        if (wins.length) out.win_id = wins[0].id;
    } catch(e) {}
    try {
        const cbs = Ext.ComponentQuery.query('combobox');
        for (const c of cbs) {
            const name = (c.getName ? c.getName() : c.name) || '';
            const label = c.fieldLabel || '';
            if (name === 'cboCapHoc') {
                out.cap_hoc = c.getValue();
                out.cap_hoc_text = c.getRawValue();
            } else if (name === 'cboTuanHoc') {
                out.tuan_hoc = c.getValue();
            } else if (name === 'cboNgayTacDung') {
                out.ngay_tac_dung_tkb = c.getValue();
            } else if (label === 'G.viên') {
                out.giao_vien_id = c.getValue();
                out.giao_vien_name = c.getRawValue();
            }
        }
    } catch(e) { out.err = String(e); }

    // Khôi phục my_token nếu chưa có — đọc từ jQuery ajaxSetup hoặc cookie
    if (!out.my_token) {
        try {
            // jQuery ajaxSetup không expose my_token trực tiếp, nhưng VnEdu nhúng
            // my_token vào URL của mọi XHR. Bắt 1 token từ XHR log nếu có.
            if (window.__xhrLog && window.__xhrLog.length) {
                for (const x of window.__xhrLog.slice().reverse()) {
                    const m = String(x.url || '').match(/my_token=([a-f0-9]+)/);
                    if (m) { out.my_token = m[1]; break; }
                }
            }
        } catch(e) {}
    }
    return out;
}
"""

# Fetch endpoint qua page.evaluate (giữ cookie session)
_JS_FETCH = r"""
async (req) => {
    const t0 = Date.now();
    try {
        const url = req.url;
        const init = {
            method: req.method || 'POST',
            credentials: 'include',
            __khdhToolRequest: true,
            headers: req.headers || {'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'},
        };
        if (req.body != null) init.body = req.body;
        const r = await fetch(url, init);
        const text = await r.text();
        return {ok: true, status: r.status, text: text, duration_ms: Date.now() - t0};
    } catch(e) {
        return {ok: false, error: String(e), duration_ms: Date.now() - t0};
    }
}
"""

# Tiết TKB từ form trong DOM (dùng cho save: tuNgay/denNgay)
_JS_GET_DATE_RANGE = r"""
() => {
    try {
        const winId = (() => {
            const wins = Ext.ComponentQuery.query('window').filter(w => /Kế hoạch dạy học/.test(w.title || ''));
            return wins.length ? wins[0].id : '';
        })();
        if (!winId) return {ok: false, err: 'no_winId'};
        const tuNgay = Ext.getCmp(winId + '_tuNgay');
        const denNgayInputs = document.querySelectorAll(`#${winId}_frm input[name="denNgay"]`);
        let denNgayVal = '';
        denNgayInputs.forEach(inp => { if (inp.value) denNgayVal = inp.value; });
        return {
            ok: true,
            tuNgay: tuNgay ? (tuNgay.getRawValue ? tuNgay.getRawValue() : '') : '',
            denNgay: denNgayVal,
        };
    } catch(e) { return {ok: false, err: String(e)}; }
}
"""

# Click nút "Lưu" qua handler để giữ behavior (log, mask, etc.)
_JS_CLICK_SAVE = r"""
() => {
    try {
        const btn = Ext.ComponentQuery.query('button').find(b => /^Lưu$/i.test(String(b.text || '').trim()) && b.handler);
        if (!btn) return {ok: false, err: 'no_save_btn'};
        btn.handler.call(btn.scope || btn);
        return {ok: true};
    } catch(e) { return {ok: false, err: String(e)}; }
}
"""

# Đóng tất cả Ext.MessageBox / Ext.Window có liên quan để pipeline không bị
# kẹt bởi dialog "Chưa chọn lớp/môn báo giảng?" (handler change của
# cboTrangThai), "Đã lưu thành công!" (sau save), "Còn tồn tại các ô chưa
# nhập đủ" (validation), v.v.
# Trả số dialog đã đóng + danh sách title/msg để caller biết loại nào.
_JS_DISMISS_DIALOGS = r"""
() => {
    try {
        const wins = Ext.ComponentQuery.query('messagebox, window');
        const closed = [];
        for (const w of wins) {
            try {
                if (!(w.isVisible && w.isVisible())) continue;
                /* Bỏ qua các window chính (KHDH, popup chính). Chỉ đóng
                   messagebox + dialog nhỏ (200-450 px width). */
                const W = (w.getWidth ? w.getWidth() : 0);
                const isMsgBox = String(w.xtype || '').indexOf('messagebox') >= 0;
                const isDialog = isMsgBox || (W > 0 && W <= 500);
                if (!isDialog) continue;
                const title = String(w.title || '').slice(0, 80);
                const msg = String(
                    (w.msg || '') ||
                    (w.body && w.body.dom ? w.body.dom.innerText : '')
                ).slice(0, 200);
                if (w.close) w.close();
                else if (w.hide) w.hide();
                closed.push({title: title, msg: msg});
            } catch(e) {}
        }
        return {ok: true, closed: closed};
    } catch(e) { return {ok: false, err: String(e)}; }
}
"""

# Reload bảng KHDH (= click Refresh)
_JS_RELOAD_TABLE = r"""
() => {
    try {
        const winId = (() => {
            const wins = Ext.ComponentQuery.query('window').filter(w => /Kế hoạch dạy học/.test(w.title || ''));
            return wins.length ? wins[0].id : '';
        })();
        if (!winId) return {ok: false, err: 'no_winId'};
        const btn = Ext.getCmp(winId + '_btnRefresh');
        if (btn && btn.handler) { btn.handler.call(btn.scope || btn); return {ok: true}; }
        // Fallback: gọi loadData nếu có
        if (typeof loadData === 'function') { loadData(); return {ok: true, msg: 'loadData'}; }
        return {ok: false, err: 'no_refresh'};
    } catch(e) { return {ok: false, err: String(e)}; }
}
"""

# Bật chế độ Sửa (Gợi ý theo TKB)
_JS_SET_GOI_Y_TKB = r"""
() => {
    try {
        const r = Ext.getCmp('rdoEdit2');
        if (!r) return {ok: false, err: 'rdoEdit2_not_found'};
        // C6 fix: check visibility & disabled trước khi setValue
        if (r.isVisible && !r.isVisible()) return {ok: false, err: 'rdoEdit2_hidden'};
        if (r.isDisabled && r.isDisabled()) return {ok: false, err: 'rdoEdit2_disabled'};
        if (r.getValue && r.getValue()) return {ok: true, msg: 'already'};
        if (r.setValue) { r.setValue(true); return {ok: true, msg: 'set'}; }
        return {ok: false, err: 'no_setValue'};
    } catch(e) { return {ok: false, err: String(e)}; }
}
"""

# Bật chế độ Sửa (không có gợi ý TKB) — mode mặc định cho khi save
_JS_SET_EDIT = r"""
() => {
    try {
        const r = Ext.getCmp('rdoEdit');
        if (!r) return {ok: false, err: 'rdoEdit_not_found'};
        // C6 fix: check visibility & disabled trước khi setValue
        if (r.isVisible && !r.isVisible()) return {ok: false, err: 'rdoEdit_hidden'};
        if (r.isDisabled && r.isDisabled()) return {ok: false, err: 'rdoEdit_disabled'};
        if (r.getValue && r.getValue()) return {ok: true, msg: 'already'};
        if (r.setValue) { r.setValue(true); return {ok: true, msg: 'set'}; }
        return {ok: false, err: 'no_setValue'};
    } catch(e) { return {ok: false, err: String(e)}; }
}
"""

# Đổi tuần đang chọn trên combobox
# Đổi tuần đang chọn trên combobox + click Refresh để force reload table.
# cboTuanHoc là ExtJS combobox không có store (load từ HTML render server-side).
# Cách đúng: setValue + fireEvent('select', ...) + click Refresh.
_JS_SELECT_WEEK = r"""
(weekNum) => {
    try {
        const w = Ext.ComponentQuery.query('combobox').find(c =>
            (c.getName ? c.getName() : c.name) === 'cboTuanHoc');
        if (!w) return {ok: false, err: 'no_combo'};
        const tuan = parseInt(weekNum, 10);
        if (!w.setValue) return {ok: false, err: 'no_setValue'};
        const before = w.getValue ? w.getValue() : null;
        w.setValue(tuan);
        // Fire select event để các listener (bao gồm reload table) chạy
        try { w.fireEvent('select', w); } catch(e) {}
        try { w.fireEvent('change', w, tuan, before); } catch(e) {}
        // Click Refresh button để chắc chắn server reload đúng tuần
        const wins = Ext.ComponentQuery.query('window').filter(win =>
            /Kế hoạch dạy học/.test(win.title || ''));
        if (wins.length) {
            const winId = wins[0].id;
            const btn = Ext.getCmp(winId + '_btnRefresh');
            if (btn && btn.handler) {
                btn.handler.call(btn.scope || btn);
            }
        }
        return {ok: true, before: before, after: w.getValue()};
    } catch(e) { return {ok: false, err: String(e)}; }
}
"""

# Install XHR sniffer (idempotent) — capture method, url, status, body, response.
# Force reinstall mỗi lần KHDHClient init: dù sniffer v1 cũ đang chạy, mình
# vẫn restore prototype về native trước, rồi patch lại với v2.
_JS_INSTALL_SNIFFER = r"""
() => {
    /* Lưu native prototype 1 lần duy nhất (lần đầu page load).
       Sau đó mỗi lần install, restore từ native rồi patch v2 lên. */
    if (!window.__xhrNativeOpen) {
        /* Lần đầu — backup native (giả định chưa bị patch).
           Nếu trang đã có sniffer khác patch trước đó, native = sniffer đó.
           Đây là tradeoff chấp nhận được: ít nhất ta không double-patch
           với chính sniffer của mình. */
        window.__xhrNativeOpen = XMLHttpRequest.prototype.open;
        window.__xhrNativeSend = XMLHttpRequest.prototype.send;
    } else {
        /* Restore về native trước khi patch lại — tránh chain v1→v2→v3… */
        XMLHttpRequest.prototype.open = window.__xhrNativeOpen;
        XMLHttpRequest.prototype.send = window.__xhrNativeSend;
    }
    window.__xhrLog = [];
    window.__xhrLogV2 = true;
    const origOpen = window.__xhrNativeOpen;
    const origSend = window.__xhrNativeSend;
    XMLHttpRequest.prototype.open = function(method, url) {
        this.__method = method; this.__url = url;
        return origOpen.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function(body) {
        const ts = Date.now();
        this.addEventListener('loadend', () => {
            try {
                window.__xhrLog.push({
                    method: this.__method,
                    url: String(this.__url || '').slice(0, 400),
                    status: this.status,
                    duration_ms: Date.now() - ts,
                    body_excerpt: typeof body === 'string' ? body.slice(0, 4000) : '',
                    response_excerpt: (() => {
                        try {
                            const t = (this.responseType === '' || this.responseType === 'text')
                                ? this.responseText : '';
                            return t.slice(0, 4000);
                        } catch(e) { return ''; }
                    })(),
                });
                if (window.__xhrLog.length > 200) window.__xhrLog.shift();
            } catch(e) {}
        });
        return origSend.apply(this, arguments);
    };
    return {installed: true};
}
"""


# v3.3: Block autofill của web trong lúc tool nhập.
#
# Vấn đề: web KHDH bind handler `change` trên cboMonHoc/cboPhanMon gọi
# `getSuggestTietPpct(this)` + `getTenBaiHoc(this)` async qua jQuery AJAX.
# `getSuggestTietPpct` gọi `edu.phan_phoi_chuong_trinh.getSuggestTietPpct`;
# nếu response không có `data.tiet`, web success handler sẽ set rỗng
# txtTietPPCT/txtTenBai/txtGhiChu. Response về sau Phase D/D2 có thể xóa
# PPCT tool vừa nhập.
#
# Fix: patch tầng network trong thời gian fill để block đúng endpoint
# autofill. Patch phải re-arm được sau mỗi lần sniffer reinstall: sniffer
# restore XMLHttpRequest về native trước khi patch lại, nên blocker cũ có
# thể bị tháo dù flag `__khdhAutofillBlockerInstalled` vẫn còn true.
# Tool fetch có `__khdhToolRequest` để bypass blocker.
_JS_INSTALL_AUTOFILL_BLOCKER = r"""
() => {
    window.__khdhBlockAutofill = !!window.__khdhBlockAutofill;

    const isAutofillRequest = (url, body) => {
        const s = String(url || '') + '\n' + String(body || '');
        // v3.3: Auto-detect endpoint autofill mở rộng:
        //  1. Endpoint cũ đã biết: getSuggestTietPpct, getByTiet, getTenBaiHoc
        //  2. Mọi method mới trong namespace `phan_phoi_chuong_trinh.*` có
        //     prefix get/find/suggest/lookup/auto/load/fetch + tham chiếu
        //     đến tiet/ppct/ten_bai/lich_bao_giang.
        //  3. KHÔNG match endpoint save/delete/update của KHDH.
        if (/(?:getSuggestTietPpct|getByTiet|getTenBaiHoc)/i.test(s)) {
            return true;
        }
        // Heuristic: namespace phan_phoi_chuong_trinh + verb get/find/...
        if (/phan_phoi_chuong_trinh\.[\w]*?(get|find|suggest|lookup|auto|load|fetch)[\w]*/i.test(s)) {
            // Loại trừ các endpoint save/update/delete (case web đặt tên lạ)
            if (!/(?:save|update|delete|remove|set|insert|create)/i.test(s)) {
                return true;
            }
        }
        return false;
    };

    const rememberBlocked = (transport, url, body) => {
        try {
            if (!Array.isArray(window.__khdhBlockedAutofillLog)) {
                window.__khdhBlockedAutofillLog = [];
            }
            window.__khdhBlockedAutofillLog.push({
                ts: Date.now(),
                transport: transport,
                url: String(url || '').slice(0, 500),
                body_excerpt: typeof body === 'string' ? body.slice(0, 1000) : '',
            });
            if (window.__khdhBlockedAutofillLog.length > 100) {
                window.__khdhBlockedAutofillLog.shift();
            }
        } catch(e) {}
    };

    window.__khdhIsAutofillRequest = isAutofillRequest;
    window.__khdhRememberBlockedAutofill = rememberBlocked;

    window.__khdhInstallAutofillBlocker = function() {
        const xhrAlreadyArmed =
            XMLHttpRequest.prototype.open === window.__khdhBlockerOpen &&
            XMLHttpRequest.prototype.send === window.__khdhBlockerSend;
        const fetchAlreadyArmed =
            !window.fetch || window.fetch === window.__khdhBlockerFetch;
        const scriptAlreadyArmed =
            Element.prototype.appendChild === window.__khdhBlockerAppendChild &&
            Element.prototype.insertBefore === window.__khdhBlockerInsertBefore;

        if (xhrAlreadyArmed && fetchAlreadyArmed && scriptAlreadyArmed) {
            window.__khdhAutofillBlockerInstalled = true;
            return {ok: true, msg: 'already', armed: true};
        }

        const origOpen = xhrAlreadyArmed && window.__khdhBlockerOrigOpen
            ? window.__khdhBlockerOrigOpen
            : XMLHttpRequest.prototype.open;
        const origSend = xhrAlreadyArmed && window.__khdhBlockerOrigSend
            ? window.__khdhBlockerOrigSend
            : XMLHttpRequest.prototype.send;

        const blockerOpen = function(method, url) {
            this.__khdhUrl = String(url || '');
            return origOpen.apply(this, arguments);
        };
        const blockerSend = function(body) {
            const u = String(this.__khdhUrl || this.__url || '');
            if (window.__khdhBlockAutofill && isAutofillRequest(u, body)) {
                rememberBlocked('xhr', u, body);
                try { this.abort(); } catch(e) {}
                return;
            }
            return origSend.apply(this, arguments);
        };
        blockerOpen.__khdhAutofillBlocker = true;
        blockerSend.__khdhAutofillBlocker = true;
        window.__khdhBlockerOrigOpen = origOpen;
        window.__khdhBlockerOrigSend = origSend;
        window.__khdhBlockerOpen = blockerOpen;
        window.__khdhBlockerSend = blockerSend;
        XMLHttpRequest.prototype.open = blockerOpen;
        XMLHttpRequest.prototype.send = blockerSend;

        if (window.fetch) {
            const origFetch = fetchAlreadyArmed && window.__khdhBlockerOrigFetch
                ? window.__khdhBlockerOrigFetch
                : window.fetch;
            const blockerFetch = function(input, init) {
                const url = typeof input === 'string'
                    ? input
                    : (input && input.url) || '';
                const body = init && init.body;
                const isToolRequest = !!(init && init.__khdhToolRequest);
                if (
                    window.__khdhBlockAutofill &&
                    !isToolRequest &&
                    isAutofillRequest(url, body)
                ) {
                    rememberBlocked('fetch', url, body);
                    const err = new Error('KHDH autofill request blocked');
                    err.name = 'AbortError';
                    return Promise.reject(err);
                }
                return origFetch.apply(this, arguments);
            };
            blockerFetch.__khdhAutofillBlocker = true;
            window.__khdhBlockerOrigFetch = origFetch;
            window.__khdhBlockerFetch = blockerFetch;
            window.fetch = blockerFetch;
        }

        const shouldBlockScript = (node) => {
            try {
                return !!(
                    node &&
                    String(node.tagName || '').toUpperCase() === 'SCRIPT' &&
                    isAutofillRequest(node.src || node.getAttribute('src') || '', '')
                );
            } catch(e) {
                return false;
            }
        };
        const origAppendChild = scriptAlreadyArmed && window.__khdhBlockerOrigAppendChild
            ? window.__khdhBlockerOrigAppendChild
            : Element.prototype.appendChild;
        const origInsertBefore = scriptAlreadyArmed && window.__khdhBlockerOrigInsertBefore
            ? window.__khdhBlockerOrigInsertBefore
            : Element.prototype.insertBefore;
        const blockerAppendChild = function(child) {
            if (window.__khdhBlockAutofill && shouldBlockScript(child)) {
                rememberBlocked('script', child.src || child.getAttribute('src') || '', '');
                return child;
            }
            return origAppendChild.apply(this, arguments);
        };
        const blockerInsertBefore = function(newNode, referenceNode) {
            if (window.__khdhBlockAutofill && shouldBlockScript(newNode)) {
                rememberBlocked('script', newNode.src || newNode.getAttribute('src') || '', '');
                return newNode;
            }
            return origInsertBefore.apply(this, arguments);
        };
        blockerAppendChild.__khdhAutofillBlocker = true;
        blockerInsertBefore.__khdhAutofillBlocker = true;
        window.__khdhBlockerOrigAppendChild = origAppendChild;
        window.__khdhBlockerOrigInsertBefore = origInsertBefore;
        window.__khdhBlockerAppendChild = blockerAppendChild;
        window.__khdhBlockerInsertBefore = blockerInsertBefore;
        Element.prototype.appendChild = blockerAppendChild;
        Element.prototype.insertBefore = blockerInsertBefore;

        window.__khdhAutofillBlockerInstalled = true;
        return {ok: true, msg: 'installed', armed: true};
    };

    return window.__khdhInstallAutofillBlocker();
}
"""

_JS_SET_BLOCK_AUTOFILL = r"""
(blocked) => {
    try {
        if (typeof window.__khdhInstallAutofillBlocker === 'function') {
            window.__khdhInstallAutofillBlocker();
        }
    } catch(e) {}
    window.__khdhBlockAutofill = !!blocked;
    return {
        ok: true,
        blocked: !!blocked,
        xhr_armed: XMLHttpRequest.prototype.send === window.__khdhBlockerSend,
        fetch_armed: !window.fetch || window.fetch === window.__khdhBlockerFetch,
        blocked_count: Array.isArray(window.__khdhBlockedAutofillLog)
            ? window.__khdhBlockedAutofillLog.length
            : 0,
    };
}
"""


# Fetch nhiều tuần trong 1 lần page.evaluate qua Promise.all.
# Tăng tốc 5-8x so với fetch tuần tự (test thực tế: 3 tuần ~1.2s thay vì 3.6s).
# Mỗi tuần gọi cùng endpoint `lich_bao_giang`, server xử lý song song được.
_JS_FETCH_WEEKS_BATCH = r"""
async (args) => {
    const ctx = args.ctx || {};
    const weeks = Array.isArray(args.weeks) ? args.weeks : [];
    const isEdit = args.is_edit || 1;
    if (!ctx.my_token || !ctx.nam_hoc) {
        return {ok: false, err: 'no_context'};
    }
    const fetchOne = async (w) => {
        const params = new URLSearchParams();
        params.set('my_token', String(ctx.my_token));
        params.set('my_user_id', String(ctx.my_user_id || ''));
        params.set('app_nam_hoc', String(ctx.nam_hoc));
        params.set('winId', String(ctx.win_id || ''));
        params.set('namHoc', String(ctx.nam_hoc));
        params.set('capHoc', String(ctx.cap_hoc || 2));
        params.set('giaoVienId', String(ctx.giao_vien_id || ''));
        params.set('tuanHoc', String(w));
        params.set('iNgayTacDung', String(ctx.ngay_tac_dung || ''));
        params.set('isEdit', String(isEdit));
        const url = '?load=edu.lich_bao_giang.lich_bao_giang'
            + '&app_nam_hoc=' + encodeURIComponent(ctx.nam_hoc)
            + '&my_token=' + encodeURIComponent(ctx.my_token);
        const t0 = performance.now();
        try {
            const resp = await fetch(url, {
                method: 'POST', credentials: 'include',
                __khdhToolRequest: true,
                headers: {'content-type': 'application/x-www-form-urlencoded; charset=UTF-8'},
                body: params.toString(),
            });
            const text = await resp.text();
            return {
                week: w, ok: resp.status === 200, status: resp.status,
                duration_ms: Math.round(performance.now() - t0),
                text: text,
            };
        } catch (e) {
            return {
                week: w, ok: false, status: 0,
                duration_ms: Math.round(performance.now() - t0),
                err: String(e),
            };
        }
    };
    const t0 = performance.now();
    const results = await Promise.all(weeks.map(fetchOne));
    return {
        ok: true, total_ms: Math.round(performance.now() - t0),
        results: results,
    };
}
"""


# Đọc tổng số tuần từ store của cboTuanHoc — dùng để auto-detect tuan_to.
_JS_GET_TOTAL_WEEKS = r"""
() => {
    try {
        const cb = Ext.ComponentQuery.query('combobox').find(c =>
            (c.getName ? c.getName() : c.name) === 'cboTuanHoc');
        if (!cb || !cb.store || !cb.store.data) return {ok: false, err: 'no_combo'};
        const items = cb.store.data.items || [];
        if (!items.length) return {ok: false, err: 'empty_store'};
        const weeks = items.map(r => {
            try { return parseInt(r.get ? r.get('id') : r.data.id, 10); }
            catch (e) { return 0; }
        }).filter(n => n > 0);
        return {
            ok: true,
            total: weeks.length,
            min: Math.min.apply(null, weeks),
            max: Math.max.apply(null, weeks),
            current: cb.getValue ? parseInt(cb.getValue(), 10) : 0,
        };
    } catch (e) {
        return {ok: false, err: String(e)};
    }
}
"""


# ---------------------------------------------------------------
# KHDHClient
# ---------------------------------------------------------------

class KHDHClient:
    """Wrap mọi API endpoint VnEdu KHDH.

    Sử dụng:
        client = KHDHClient(page)
        ctx = client.fetch_context()
        wd = client.fetch_week(35)
        save_res = client.save_week_payload(35, payload)
    """

    def __init__(self, page, default_timeout_ms: int = 30000):
        self.page = page
        self.default_timeout_ms = default_timeout_ms
        self._context: KHDHContext | None = None
        # Apply default timeout cho mọi page operation (navigation, evaluate
        # internal navigation, wait_for_*). Trước đây giá trị này được lưu
        # nhưng KHÔNG truyền vào page → Playwright dùng default 30s cố định.
        try:
            page.set_default_timeout(default_timeout_ms)
        except Exception as e:
            logger.warning(f"set_default_timeout failed: {e}")
        # Inject sniffer ngay (idempotent)
        try:
            page.evaluate(_JS_INSTALL_SNIFFER)
        except Exception as e:
            logger.warning(f"install sniffer failed: {e}")
        # v3.2: Inject XHR autofill blocker — patch XMLHttpRequest để
        # tool có thể tạm block các request `getByTiet`/`getSuggestTietPpct`
        # của web khi đang nhập, tránh response async override PPCT đã set.
        # Patch idempotent — gọi lại không hại gì.
        try:
            page.evaluate(_JS_INSTALL_AUTOFILL_BLOCKER)
        except Exception as e:
            logger.warning(f"install autofill blocker failed: {e}")

    # -----------------------------------------------------------
    # CONTEXT
    # -----------------------------------------------------------

    def fetch_context(self, force: bool = False) -> KHDHContext:
        """Đọc context (token, user_id, gv_id, win_id, ...) từ trang đang mở.

        Retry tới 5 lần với backoff 2s nếu my_token chưa có (ExtJS chưa load,
        XHR chưa fire). Tổng max ~10s thay vì raise ngay (C4 fix).
        """
        if self._context and not force:
            return self._context

        # Retry loop: thử tối đa 5 lần với backoff
        max_attempts = 5
        backoff_s = 2.0
        raw: dict = {}
        for attempt in range(1, max_attempts + 1):
            try:
                raw = self.page.evaluate(_JS_GET_CONTEXT) or {}
            except Exception as e:
                logger.warning(f"fetch_context attempt {attempt}: evaluate failed: {e}")
                raw = {}

            if raw.get("my_token"):
                break  # Đã có token, thoát loop

            # Trên attempt 1, click Refresh để force XHR
            if attempt == 1:
                try:
                    self.page.evaluate(_JS_RELOAD_TABLE)
                except Exception:
                    pass

            # Sleep trước attempt sau (không sleep ở attempt cuối)
            if attempt < max_attempts:
                time.sleep(backoff_s)

        ctx = KHDHContext(
            my_token=str(raw.get("my_token") or ""),
            my_user_id=str(raw.get("my_user_id") or ""),
            nam_hoc=int(raw.get("nam_hoc") or 0),
            cap_hoc=int(raw.get("cap_hoc") or 0),
            cap_hoc_text=str(raw.get("cap_hoc_text") or ""),
            giao_vien_id=int(raw.get("giao_vien_id") or 0),
            giao_vien_name=str(raw.get("giao_vien_name") or ""),
            win_id=str(raw.get("win_id") or ""),
            ngay_tac_dung_tkb=str(raw.get("ngay_tac_dung_tkb") or ""),
            site_id=str(raw.get("site_id") or ""),
        )
        if not ctx.my_token:
            raise RuntimeError(
                f"Không lấy được my_token sau {max_attempts} lần thử "
                f"({max_attempts * backoff_s:.0f}s) — "
                "chưa đăng nhập VnEdu hoặc bảng KHDH chưa load"
            )
        if not ctx.giao_vien_id:
            raise RuntimeError("Không lấy được giao_vien_id — đảm bảo đang ở module KHDH")
        self._context = ctx
        return ctx

    def invalidate_context(self) -> None:
        """Xóa cache context — buộc fetch_context() refetch ở lần gọi tiếp.

        Dùng khi nghi ngờ token/session đã expire (vd response 403, hoặc
        success=false từ server). Giúp tránh tình trạng cache stale gây
        confusing error downstream (C5 fix).
        """
        self._context = None

    # -----------------------------------------------------------
    # MODE / WEEK SWITCHING
    # -----------------------------------------------------------

    def enable_goi_y_tkb_mode(self) -> bool:
        """Bật chế độ 'Sửa (Gợi ý theo TKB)' để load đầy đủ slot từ TKB.

        Dùng cho Bootstrap (lấy danh sách lớp/môn/phân môn) và Advanced
        (xem TKB pattern). KHÔNG dùng khi save vì web yêu cầu mode 'Sửa'.
        """
        r = self.page.evaluate(_JS_SET_GOI_Y_TKB)
        return bool(r and r.get("ok"))

    def enable_edit_mode(self) -> bool:
        """Bật chế độ 'Sửa' (không có gợi ý TKB).

        Đây là mode chuẩn để **save** dữ liệu. Mode 'Sửa (Gợi ý)' thường
        bị web khóa save vì nó hiển thị slot suggested chưa thực sự được
        chọn.
        """
        r = self.page.evaluate(_JS_SET_EDIT)
        return bool(r and r.get("ok"))

    def select_week_in_ui(self, tuan: int) -> bool:
        """Đổi tuần đang chọn trên combobox UI (sẽ trigger reload bảng)."""
        r = self.page.evaluate(_JS_SELECT_WEEK, tuan)
        return bool(r and r.get("ok"))

    def reload_table(self):
        """Click Refresh để reload bảng KHDH."""
        return self.page.evaluate(_JS_RELOAD_TABLE)

    def reload_table_and_wait(
        self, floor_s: float = 1.5, max_extra_s: float = 6.0,
        stop_event: "threading.Event | None" = None,
    ) -> bool:
        """(#3) Reload bảng + chờ DOM render xong, thay cho sleep cứng.

        No-downside so với `reload_table() + time.sleep(floor_s)`:
          - VẪN chờ tối thiểu `floor_s` (giữ nguyên hành vi đã chứng minh
            chạy được — không proceed sớm hơn hiện trạng).
          - Sau floor, NẾU bảng chưa render (không có ô cboLopHoc nào),
            chờ THÊM tối đa `max_extra_s` đến khi render — giải quyết case
            mạng trường học chậm khiến 1.5s không đủ → trước đây ghi khi
            DOM chưa sẵn sàng → mất tiết.

        Returns:
            True nếu bảng đã render (hoặc floor đã đủ). False nếu hết
            max_extra mà vẫn chưa thấy ô (caller vẫn proceed — verify-after-
            save sẽ là lưới an toàn cuối).
        """
        try:
            self.reload_table()
        except Exception as e:
            logger.warning(f"reload_table_and_wait: reload failed: {e}")
        # Floor: chờ tối thiểu (interruptible)
        slept = 0.0
        while slept < floor_s:
            if stop_event is not None and stop_event.is_set():
                return False
            step = min(0.1, floor_s - slept)
            time.sleep(step)
            slept += step
        # Sau floor: poll DOM ready, chờ thêm tối đa max_extra_s
        deadline = time.monotonic() + max_extra_s
        while time.monotonic() < deadline:
            if stop_event is not None and stop_event.is_set():
                return False
            try:
                ready = self.page.evaluate(
                    "() => !!document.querySelector('[id^=\"cboLopHoc_\"]')"
                )
                if ready:
                    return True
            except Exception:
                pass
            time.sleep(0.2)
        return False

    # -----------------------------------------------------------
    # CORE FETCH/POST
    # -----------------------------------------------------------

    def _do_fetch(
        self,
        url: str,
        method: str = "POST",
        body: str | None = None,
        headers: dict[str, str] | None = None,
    ) -> ApiResult:
        """Fetch qua page.evaluate. Trả ApiResult với raw text."""
        req = {
            "url": url,
            "method": method,
            "body": body,
            "headers": headers or {"Content-Type": "application/x-www-form-urlencoded; charset=UTF-8"},
        }
        try:
            res = self.page.evaluate(_JS_FETCH, req)
        except Exception as e:
            return ApiResult(ok=False, error=f"page.evaluate: {type(e).__name__}: {e}")
        if not res or not res.get("ok"):
            return ApiResult(ok=False, error=res.get("error", "fetch_failed"),
                            duration_ms=int(res.get("duration_ms", 0) if res else 0))
        status = int(res.get("status") or 0)
        # Auth invalidation: nếu server trả 401/403 → cache context có thể
        # đã stale (token expired, user logged out). Clear cache để lần fetch
        # tiếp theo refetch context fresh từ ExtJS (C5 fix).
        if status in (401, 403):
            logger.warning(f"_do_fetch: status={status} → invalidate context cache")
            self.invalidate_context()
        return ApiResult(ok=True, status=status,
                        raw=res.get("text") or "",
                        duration_ms=int(res.get("duration_ms") or 0))

    @staticmethod
    def _build_form_body(params: dict[str, Any]) -> str:
        """Encode dict thành application/x-www-form-urlencoded (giữ thứ tự, escape)."""
        from urllib.parse import quote
        parts = []
        for k, v in params.items():
            if v is None:
                v = ""
            elif isinstance(v, bool):
                v = "1" if v else "0"
            else:
                v = str(v)
            parts.append(f"{quote(str(k), safe='')}={quote(v, safe='')}")
        return "&".join(parts)

    # -----------------------------------------------------------
    # ENDPOINT WRAPPERS
    # -----------------------------------------------------------

    def fetch_week(self, tuan: int, is_edit: int = 2) -> WeekData:
        """[#1] Đọc 1 tuần KHDH.

        is_edit: 1=Sửa, 2=Sửa (Gợi ý theo TKB)

        Returns: WeekData
        Raises: RuntimeError nếu API fail.
        """
        ctx = self.fetch_context()
        url = f"?load=edu.lich_bao_giang.lich_bao_giang&app_nam_hoc={ctx.nam_hoc}&my_token={ctx.my_token}"
        params = {
            "my_token": ctx.my_token,
            "my_user_id": ctx.my_user_id,
            "app_nam_hoc": ctx.nam_hoc,
            "winId": ctx.win_id,
            "namHoc": ctx.nam_hoc,
            "capHoc": ctx.cap_hoc,
            "giaoVienId": ctx.giao_vien_id,
            "tuanHoc": tuan,
            "iNgayTacDung": ctx.ngay_tac_dung_tkb,
            "isEdit": is_edit,
        }
        body = self._build_form_body(params)
        res = self._do_fetch(url, method="POST", body=body)
        if not res.ok or res.status != 200:
            raise RuntimeError(f"fetch_week({tuan}) failed: status={res.status} err={res.error}")
        return parse_load_response(res.raw, tuan)

    def fetch_weeks_parallel(
        self,
        tuans: list[int],
        is_edit: int = 1,
        batch_size: int = 6,
        on_batch: Callable[[int, int, list[int]], None] | None = None,
        stop_event: threading.Event | None = None,
    ) -> dict[int, WeekData]:
        """Fetch nhiều tuần SONG SONG qua `Promise.all` trong 1 page.evaluate.

        Cải tiến đáng kể so với fetch tuần tự: test thực tế cho thấy
        6 tuần/batch mất ~1.5s thay vì ~6s tuần tự. Server VnEdu xử lý
        nhiều request `lich_bao_giang` song song được.

        Args:
            tuans: list các số tuần cần fetch.
            is_edit: 1=Sửa, 2=Sửa (Gợi ý theo TKB). Mặc định 1 cho detect.
            batch_size: số tuần mỗi batch. 6 là sweet spot — đủ nhanh nhưng
                không quá tải server (mỗi response ~180KB).
            on_batch: callback(done_count, total, batch_weeks) sau mỗi batch.
            stop_event: cho phép user dừng giữa chừng.

        Returns:
            dict {week_num: WeekData}. Tuần fail bị skip (không có trong dict).
        """
        ctx = self.fetch_context()
        ctx_dict = {
            "my_token": ctx.my_token,
            "my_user_id": ctx.my_user_id,
            "nam_hoc": ctx.nam_hoc,
            "cap_hoc": ctx.cap_hoc,
            "giao_vien_id": ctx.giao_vien_id,
            "win_id": ctx.win_id,
            "ngay_tac_dung": ctx.ngay_tac_dung_tkb,
        }

        out: dict[int, WeekData] = {}
        total = len(tuans)
        done = 0
        for i in range(0, total, batch_size):
            if stop_event is not None and stop_event.is_set():
                break
            batch = tuans[i:i + batch_size]
            try:
                resp = self.page.evaluate(
                    _JS_FETCH_WEEKS_BATCH,
                    {"ctx": ctx_dict, "weeks": batch, "is_edit": is_edit},
                )
            except Exception as e:
                logger.warning(f"fetch_weeks_parallel batch {batch} failed: {e}")
                done += len(batch)
                if on_batch:
                    on_batch(done, total, batch)
                continue
            if not resp or not resp.get("ok"):
                err = resp.get("err", "fetch_failed") if resp else "no_response"
                logger.warning(f"fetch_weeks_parallel batch {batch} err: {err}")
                done += len(batch)
                if on_batch:
                    on_batch(done, total, batch)
                continue
            for r in resp.get("results", []):
                w = int(r.get("week") or 0)
                if not r.get("ok"):
                    continue
                text = r.get("text") or ""
                if not text:
                    continue
                try:
                    wd = parse_load_response(text, w)
                    out[w] = wd
                except Exception as parse_e:
                    logger.warning(f"parse week {w}: {parse_e}")
            done += len(batch)
            if on_batch:
                on_batch(done, total, batch)
        return out

    def get_total_weeks(self) -> dict:
        """Đọc tổng số tuần từ combobox `cboTuanHoc` trên web.

        Returns:
            {ok: bool, total: int, min: int, max: int, current: int} hoặc
            {ok: False, err: str}.
        """
        try:
            return self.page.evaluate(_JS_GET_TOTAL_WEEKS) or {"ok": False}
        except Exception as e:
            return {"ok": False, "err": str(e)}

    def save_week_payload(self, tuan: int, fields: dict[str, str], tu_ngay: str = "", den_ngay: str = "") -> SaveResult:
        """[#2] Lưu 1 tuần với payload tự build.

        Args:
            tuan: số tuần
            fields: dict các field {field_id: value} cần override (vd
                {"txtTenBai_2_2_1": "Unit X", "txtTietPPCT_2_2_1": "103"}).
                Các field không truyền sẽ giữ nguyên giá trị hiện tại.
            tu_ngay, den_ngay: dạng dd/MM/yyyy. Nếu rỗng thì đọc từ form hiện tại.

        Lưu ý: Endpoint này yêu cầu **toàn bộ form 70 row × 8 field**.
        Nếu chỉ truyền 1 field, server sẽ lưu mỗi field đó nhưng các slot khác
        có thể bị reset. → Khuyến nghị: dùng `save_week_via_button()` để click Lưu
        trên UI sau khi đã set values vào DOM.

        Returns: SaveResult
        """
        ctx = self.fetch_context()
        # Đọc tu_ngay / den_ngay từ form nếu chưa truyền
        if not tu_ngay or not den_ngay:
            r = self.page.evaluate(_JS_GET_DATE_RANGE)
            if r and r.get("ok"):
                tu_ngay = tu_ngay or r.get("tuNgay") or ""
                den_ngay = den_ngay or r.get("denNgay") or ""

        params: dict[str, Any] = {
            "iNamHoc": ctx.nam_hoc,
            "capHoc": ctx.cap_hoc,
            "iGiaoVienId": ctx.giao_vien_id,
            "iTuanHoc": tuan,
            "tuNgay": tu_ngay,
            "denNgay": den_ngay,
        }
        params.update(fields)
        body = self._build_form_body(params)
        url = f"?call=edu.lich_bao_giang.save&app_nam_hoc={ctx.nam_hoc}&my_token={ctx.my_token}"
        res = self._do_fetch(url, method="POST", body=body)
        return self._parse_save_response(res)

    def save_week_via_button(self, wait_s: float = 10.0) -> SaveResult:
        """[#2 alternative] Click nút Lưu trên UI và chờ XHR save quay về.

        Cách này an toàn nhất vì web tự serialize form đầy đủ, không sợ thiếu field.
        Caller phải đảm bảo trước đó đã set values vào DOM (qua DOM manipulation).

        Returns: SaveResult — đọc raw body từ XHR sniffer (đã capture full response)
        """
        ctx = self.fetch_context()
        # Đóng các dialog tiền nhiệm (vd "Chưa chọn lớp báo giảng?" do
        # set cboTrangThai trước đó) để không che nút Lưu.
        try:
            self.dismiss_dialogs()
        except Exception:
            pass
        # Clear save XHRs cũ
        self.page.evaluate(
            "() => { if (window.__xhrLog) { window.__xhrLog = window.__xhrLog.filter(x => !/lich_bao_giang.save/.test(x.url || '')); } return true; }"
        )
        # Click Save
        r = self.page.evaluate(_JS_CLICK_SAVE)
        if not r or not r.get("ok"):
            return SaveResult(ok=False, success=False,
                            msg=f"click_save_failed: {r and r.get('err')}")
        # Wait for save XHR to complete. Có thể nhiều entry trong log do
        # sniffer cũ còn patch (v1 không có response_excerpt). Phải lấy
        # entry mới nhất CÓ response_excerpt thực sự (entry v2 đầy đủ).
        deadline = time.monotonic() + wait_s
        last_save_xhr = None
        while time.monotonic() < deadline:
            time.sleep(0.3)
            log = self.page.evaluate(
                "() => (window.__xhrLog || []).filter(x => /lich_bao_giang.save/.test(x.url || ''))"
            )
            # Tìm entry MỚI NHẤT có response_excerpt
            best = None
            for x in reversed(log):
                if x.get("response_excerpt"):
                    best = x
                    break
            if best:
                last_save_xhr = best
                # Đợi thêm chút để chắc response đã capture đầy đủ
                time.sleep(0.4)
                log2 = self.page.evaluate(
                    "() => (window.__xhrLog || []).filter(x => /lich_bao_giang.save/.test(x.url || ''))"
                )
                best2 = None
                for x in reversed(log2):
                    if x.get("response_excerpt"):
                        best2 = x
                        break
                if best2:
                    last_save_xhr = best2
                break
            elif log:
                # Có XHR save nhưng chưa có response_excerpt — chờ tiếp
                continue

        # Đóng dialog "Đã lưu thành công!" / "Còn tồn tại các ô chưa nhập đủ"
        # để các thao tác kế tiếp không bị che. Đợi 0.5s cho dialog hiện ra
        # rồi mới đóng (vì handler success/fail chạy async sau XHR).
        time.sleep(0.5)
        try:
            self.dismiss_dialogs()
        except Exception:
            pass

        if not last_save_xhr:
            return SaveResult(ok=False, success=False,
                            msg="Hết thời gian chờ phản hồi từ web. "
                                "Có thể web bị nghẽn — kiểm tra lại trên trình duyệt.")

        status = int(last_save_xhr.get("status") or 0)
        resp_text = last_save_xhr.get("response_excerpt") or ""

        # Build pseudo ApiResult để dùng _parse_save_response
        ar = ApiResult(ok=True, status=status, raw=resp_text,
                       duration_ms=int(last_save_xhr.get("duration_ms") or 0))
        if not resp_text:
            # FAIL-SAFE: không có response body = không xác minh được kết quả.
            # Trả ok=False để halt-on-error trigger, an toàn hơn coi như success.
            return SaveResult(
                ok=False, success=False,
                msg=f"Web trả status={status} nhưng không đọc được nội dung "
                    f"phản hồi. Để an toàn, tool dừng để bạn kiểm tra lại "
                    f"trên web xem tuần này đã lưu chưa.",
            )
        return self._parse_save_response(ar)

    def dismiss_dialogs(self) -> dict:
        """Đóng các dialog Ext.MessageBox / popup nhỏ đang hiện.

        Trả dict {ok, closed: list[{title, msg}]} — caller dùng để biết
        đã đóng dialog gì (vd dialog "Chưa chọn lớp" cảnh báo benign).
        """
        try:
            return self.page.evaluate(_JS_DISMISS_DIALOGS)
        except Exception as e:
            return {"ok": False, "err": f"{type(e).__name__}: {e}"}

    def get_blocked_autofill_stats(self) -> dict:
        """Trả số XHR/fetch/script tag đã bị blocker abort.

        Returns:
            {ok, count, by_transport: {xhr: N, fetch: N, script: N},
             recent: [last 5 entries]}
        Hoặc {ok: False} nếu blocker chưa được install.
        """
        try:
            res = self.page.evaluate(r"""
() => {
    const log = window.__khdhBlockedAutofillLog;
    if (!Array.isArray(log)) return {ok: false, count: 0};
    const by = {xhr: 0, fetch: 0, script: 0};
    for (const e of log) {
        const t = String(e.transport || 'xhr');
        if (by[t] !== undefined) by[t]++;
        else by[t] = 1;
    }
    const recent = log.slice(-5).map(e => ({
        ts: e.ts, transport: e.transport,
        url: String(e.url || '').slice(0, 120),
    }));
    return {
        ok: true, count: log.length,
        by_transport: by, recent: recent,
        block_active: !!window.__khdhBlockAutofill,
    };
}
""")
            return res or {"ok": False}
        except Exception:
            return {"ok": False}

    def reset_blocked_autofill_log(self) -> None:
        """Xóa log XHR đã block — gọi đầu mỗi tuần để đếm lại."""
        try:
            self.page.evaluate(
                "() => { window.__khdhBlockedAutofillLog = []; }"
            )
        except Exception:
            pass

    @staticmethod
    def _parse_save_response(res: ApiResult) -> SaveResult:
        if not res.ok or res.status != 200:
            return SaveResult(ok=False, success=False, msg=res.error or f"status={res.status}",
                            duration_ms=res.duration_ms)
        try:
            data = json.loads(res.raw)
        except Exception as e:
            return SaveResult(ok=False, success=False, msg=f"json parse: {e}", duration_ms=res.duration_ms)
        success = bool(data.get("success"))
        errors_raw = data.get("error") or {}
        errors: list[SaveError] = []
        for fid, msg in errors_raw.items():
            # cboTrangThai_<rk> trả số (0/1/...) là status code, không phải lỗi
            if fid.startswith("cboTrangThai_"):
                continue
            # txtTenBai_ trống là warning, không phải lỗi nghiêm trọng —
            # giáo viên có thể tự bổ sung tên bài sau trên web.
            # Không coi là lỗi để tránh halt khi phân môn không có CSDL tên bài
            # (vd Hoạt động trải nghiệm, Sinh hoạt lớp...).
            if fid.startswith("txtTenBai_"):
                continue
            row_key = ""
            for prefix in ("txtTenBai_", "txtTietPPCT_", "cboLopHoc_", "cboMonHoc_",
                          "cboPhanMon_", "txtGhiChu_"):
                if fid.startswith(prefix):
                    row_key = fid[len(prefix):]
                    break
            errors.append(SaveError(field_id=fid, row_key=row_key, message=str(msg)))
        return SaveResult(
            ok=True, success=success, msg=str(data.get("msg") or ""),
            errors=errors, raw=data, duration_ms=res.duration_ms,
        )

    def gen_from_prev_week(self, tuan: int, tu_ngay: str = "", den_ngay: str = "") -> ApiResult:
        """[#3] Tạo KHDH tuần X từ tuần X-1 (web utility).

        Server sẽ copy slot từ tuần X-1 sang tuần X, tự increment PPCT.
        Đây là chức năng quan trọng nhất theo strategy bạn chọn.
        """
        ctx = self.fetch_context()
        if not tu_ngay or not den_ngay:
            r = self.page.evaluate(_JS_GET_DATE_RANGE)
            if r and r.get("ok"):
                tu_ngay = tu_ngay or r.get("tuNgay") or ""
                den_ngay = den_ngay or r.get("denNgay") or ""
        params = {
            "nam_hoc": ctx.nam_hoc,
            "cap_hoc": ctx.cap_hoc,
            "gv_id": ctx.giao_vien_id,
            "tuan": tuan,
            "tu_ngay": tu_ngay,
            "den_ngay": den_ngay,
        }
        url = f"?call=edu.lich_bao_giang.genLichBaoGiangTuan&app_nam_hoc={ctx.nam_hoc}&my_token={ctx.my_token}"
        body = self._build_form_body(params)
        res = self._do_fetch(url, method="POST", body=body)
        return self._wrap_json(res)

