# Section: planner
# ######################################################################





# ---------------------------------------------------------------
# Strategy enums
# ---------------------------------------------------------------

class PlanStrategy(Enum):
    GEN_FROM_PREV_WEEK = "gen_prev"     # Gọi API genLichBaoGiangTuan
    GEN_FROM_TKB = "gen_tkb"            # Gọi API genLichBaoGiangTuanTheoTKB
    FILL_FROM_SCRATCH = "fill_scratch"  # Tự fill từng slot
    UPDATE_EMPTY_ONLY = "update_empty"  # Chỉ điền slot trống
    EVEN_ODD_TEMPLATES = "even_odd_tpl" # Dùng KHDHProfile (1 hoặc 2 mẫu lẻ/chẵn)


class PlanMode(Enum):
    AUTO = "auto"                       # Chạy thẳng, không hỏi
    PREVIEW_APPLY = "preview"           # Generate ops, user xem rồi apply


# ---------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------

@dataclass
class FillOp:
    """1 operation: điền data cho 1 slot trên 1 tuần."""
    tuan: int
    row_key: str          # "thu_buoi_tiet"
    lop_id: str
    lop_text: str = ""
    mon_id: str = ""
    mon_text: str = ""
    phan_mon_id: str = ""
    phan_mon_text: str = ""
    ppct: int = 0
    ten_bai: str = ""

    # Optional metadata
    source: str = ""      # "catalog" | "prev_week" | "tkb" | "manual" | "backup"
    notes: str = ""       # ghi chú cho user xem
    skip: bool = False    # user uncheck → skip op này

    # v3 (backup/restore): các field mở rộng để giữ trạng thái non-BT.
    # Default rỗng → executor giữ nguyên hành vi cũ (Bình thường + ghi_chu trống).
    ghi_chu: str = ""     # txtGhiChu_<rk>
    trang_thai: str = "0" # cboTrangThai_<rk> (default = "0" = Bình thường)

    def field_dict(self) -> dict[str, str]:
        """Trả ra dict các field DOM cần set."""
        return {
            f"cboLopHoc_{self.row_key}": self.lop_id,
            f"cboMonHoc_{self.row_key}": self.mon_id,
            f"cboPhanMon_{self.row_key}": self.phan_mon_id,
            f"txtTietPPCT_{self.row_key}": str(self.ppct) if self.ppct else "",
            f"txtTenBai_{self.row_key}": self.ten_bai,
            f"txtGhiChu_{self.row_key}": self.ghi_chu or "",
            f"cboTrangThai_{self.row_key}": self.trang_thai or "0",
        }


@dataclass
class PlanRequest:
    """Yêu cầu lập kế hoạch."""
    tuan_from: int
    tuan_to: int
    strategy: PlanStrategy = PlanStrategy.GEN_FROM_PREV_WEEK
    mode: PlanMode = PlanMode.PREVIEW_APPLY

    # Filter: chỉ chạy với các (lop_id, phan_mon_id). Empty = all.
    only_lop_ids: list[str] = field(default_factory=list)
    only_phan_mon_ids: list[str] = field(default_factory=list)

    # Skip tuần đã có data (≥ N filled slots)
    skip_weeks_with_data: bool = False
    skip_threshold: int = 1

    # Auto-skip nếu đã chạy gen_prev (server tự copy đầy đủ)
    auto_skip_filled_after_gen: bool = True

    def __post_init__(self):
        if self.tuan_from > self.tuan_to:
            raise ValueError("tuan_from > tuan_to")


@dataclass
class WeekPlan:
    """Plan cho 1 tuần."""
    tuan: int
    strategy: PlanStrategy
    pre_action: str = ""           # "gen_prev" | "gen_tkb" | "" (no-op)
    pre_action_args: dict = field(default_factory=dict)
    fill_ops: list[FillOp] = field(default_factory=list)
    skip_reason: str = ""
    estimated_changes: int = 0     # số fill_ops không skip


@dataclass
class PlanReport:
    """Toàn bộ plan trên range tuần."""
    request: PlanRequest
    week_plans: list[WeekPlan] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)

    @property
    def total_ops(self) -> int:
        return sum(p.estimated_changes for p in self.week_plans)

    @property
    def total_pre_actions(self) -> int:
        return sum(1 for p in self.week_plans if p.pre_action)


# ---------------------------------------------------------------
# WeekPlanner
# ---------------------------------------------------------------

class WeekPlanner:
    """Sinh kế hoạch dựa trên YearScanReport + LessonCatalog hoặc KHDHProfile.

    2 chế độ chính:

    1. **Theo profile (mới — EVEN_ODD_TEMPLATES)**:
       Truyền `profile=KHDHProfile` (đã có TKB lẻ/chẵn + ppct_starts).
       Strategy = `EVEN_ODD_TEMPLATES`. `report` và `catalog` optional.

    2. **Theo phân tích web (cũ — các strategy khác)**:
       Truyền `report=YearScanReport` + `catalog=LessonCatalog`.
       Dùng cho tab Nâng cao.
    """

    def __init__(
        self,
        report: YearScanReport | None = None,
        catalog: LessonCatalog | None = None,
        weeks_data: dict[int, WeekData] | None = None,
        profile=None,  # Optional[KHDHProfile] — type hint string để tránh circular import
        client=None,   # Optional[KHDHClient] — dùng cho scan-before-fill (v2)
    ):
        self.report = report
        self.catalog = catalog
        self.weeks_data = weeks_data or {}
        self.profile = profile
        self.client = client
        # v2: Cache progress được scan từ web ngay trước khi build plan.
        # Key = tuan, Value = {group_key: SubjectProgress} computed từ
        # mọi tuần ≤ tuan đã scan. Reset đầu mỗi `generate_plan()`.
        self._scan_cache: dict[int, dict[str, "SubjectProgress"]] = {}
        # Cache WeekData đã fetch để tránh fetch trùng nếu cùng tuần
        # được referenced nhiều lần (perf optimization).
        self._fetched_weeks: dict[int, WeekData] = {}

    # -----------------------------------------------------------
    # Plan generation
    # -----------------------------------------------------------

    def generate_plan(self, request: PlanRequest) -> PlanReport:
        """Sinh PlanReport cho range tuần."""
        report = PlanReport(request=request)

        # Strategy EVEN_ODD_TEMPLATES dùng path riêng vì cần persist
        # progress_by_group xuyên qua các tuần (PPCT cuốn chiếu)
        if request.strategy == PlanStrategy.EVEN_ODD_TEMPLATES:
            return self._generate_even_odd_plan(request, report)

        # Strategy cũ — mỗi tuần độc lập
        if self.report is None:
            raise ValueError(
                "Strategy này yêu cầu YearScanReport. "
                "Hãy scan toàn năm trước hoặc chuyển sang EVEN_ODD_TEMPLATES."
            )
        weeks = list(range(request.tuan_from, request.tuan_to + 1))
        for tuan in weeks:
            wp = self._plan_for_week(tuan, request, report)
            report.week_plans.append(wp)
        return report

    def _generate_even_odd_plan(
        self, request: PlanRequest, report: PlanReport
    ) -> PlanReport:
        """Path riêng cho strategy EVEN_ODD_TEMPLATES.

        PPCT cuốn chiếu xuyên qua tuần, không reset mỗi tuần. Phải xử lý
        ở 1 chỗ tập trung.

        v2.1 (FIX): Profile.ppct_starts là source-of-truth TUYỆT ĐỐI.
        User đã setup PPCT bắt đầu cho tuần X bằng tay (có thể tính bù khoảng
        trống cho các tuần nghỉ), tool KHÔNG ĐƯỢC tự ý override bằng web scan.

        Logic cũ (đã rollback): scan tuần 1..tuan_from-1 → patch ppct_starts.
        → SAI vì user setup PPCT 72 cho tuần 26 (đã tính bù), web max=62 →
        tool override thành 63 → save sai PPCT.
        """
        if self.profile is None:
            raise ValueError(
                "Strategy EVEN_ODD_TEMPLATES yêu cầu KHDHProfile. "
                "Hãy truyền profile vào WeekPlanner."
            )

        # Init progress map từ ppct_starts — TUYỆT ĐỐI tôn trọng setup tay
        progress_by_group: dict[str, int] = {}
        for entry in self.profile.ppct_starts:
            progress_by_group[entry.group_key] = entry.ppct_start

        weeks = list(range(request.tuan_from, request.tuan_to + 1))
        for tuan in weeks:
            wp = self._plan_for_week_even_odd(tuan, request, progress_by_group)
            report.week_plans.append(wp)
        self._validate_counted_ppct_unique(report)
        return report

    @staticmethod
    def _validate_counted_ppct_unique(report: PlanReport) -> None:
        """Chặn trùng PPCT active trong cùng lớp/môn/phân môn trước khi ghi web."""
        seen: dict[tuple[str, int], FillOp] = {}
        for wp in report.week_plans:
            for op in wp.fill_ops:
                if op.skip or op.trang_thai not in TT_COUNTED or not op.ppct:
                    continue
                group_key = f"{op.lop_id}|{op.mon_id}|{op.phan_mon_id}"
                key = (group_key, int(op.ppct))
                old = seen.get(key)
                if old is not None:
                    raise ProfileSchemaError(
                        "PPCT.trung_active",
                        f"Trùng PPCT đang dạy {op.ppct} của "
                        f"{op.lop_text} / {op.phan_mon_text or op.mon_text}: "
                        f"tuần {old.tuan} ô {old.row_key} và tuần {op.tuan} ô {op.row_key}. "
                        "VnEdu thường sẽ không cho lưu, hãy đổi lịch Nghỉ/Dạy bù hoặc PPCT bắt đầu.",
                    )
                seen[key] = op

    def _plan_for_week_even_odd(
        self,
        tuan: int,
        request: PlanRequest,
        progress_by_group: dict[str, int],
    ) -> WeekPlan:
        """Sinh WeekPlan cho 1 tuần dùng template từ profile.

        Logic:
        1. Lấy template active: `profile.get_active_template(tuan)`
        2. Sort slots theo (thu, buoi, tiet) — đảm bảo PPCT chạy đúng thứ tự
        3. Mỗi slot: PPCT từ progress_by_group, +1 sau khi dùng
        4. Lookup tên bài từ catalog (nếu có); để rỗng nếu không có
        """
        wp = WeekPlan(tuan=tuan, strategy=PlanStrategy.EVEN_ODD_TEMPLATES)
        template = self.profile.get_active_template(tuan)

        if not template or not template.slots:
            # Tuần này không có slot trong template → skip
            wp.skip_reason = (
                f"Mẫu TKB cho tuần {tuan} "
                f"({'chẵn' if self.profile.is_chan(tuan) else 'lẻ'}) "
                "rỗng — không có tiết nào để nhập."
            )
            return wp

        # Sort slots để PPCT cuốn chiếu đúng theo thời gian thực.
        # Quy tắc Nghỉ/Dạy bù được đưa vào cùng timeline để tránh trùng
        # row_key và tránh tăng PPCT sai khi một tiết nghỉ chưa được dạy lại.
        sorted_slots = sorted(
            template.slots,
            key=lambda s: (s.thu, s.buoi, s.tiet),
        )
        template_by_key = {s.slot_key: s for s in sorted_slots}

        events_this_week = [
            e for e in profile_schedule_events(self.profile)
            if e.enabled and e.tuan == tuan
        ]
        nghi_by_key: dict[str, TKBScheduleEvent] = {}
        day_bu_by_key: dict[str, TKBScheduleEvent] = {}
        seen_positions: dict[str, TKBScheduleEvent] = {}
        for event in events_this_week:
            existing = seen_positions.get(event.row_key)
            if existing is not None:
                raise ProfileSchemaError(
                    "NghiDayBu.trung_o",
                    f"Tuần {tuan}, {event.label} bị trùng vị trí "
                    f"thứ {event.thu}, buổi {event.buoi}, tiết {event.tiet} "
                    f"với {existing.label}.",
                )
            seen_positions[event.row_key] = event
            if event.kind == TKB_EVENT_NGHI:
                nghi_by_key[event.row_key] = event
            elif event.kind == TKB_EVENT_DAY_BU:
                day_bu_by_key[event.row_key] = event

        def _slot_key_sort(row_key: str) -> tuple[int, int, int]:
            try:
                thu, buoi, tiet = (int(x) for x in row_key.split("_", 2))
                return thu, buoi, tiet
            except Exception:
                return 99, 99, 99

        def _make_op(
            *,
            slot: SlotEntry,
            row_key: str,
            ppct: int,
            trang_thai: str,
            ghi_chu: str = "",
            notes: str = "",
            source: str = "tkb",
        ) -> FillOp:
            ten_bai = self._lookup_ten_bai(
                slot.lop_id, slot.mon_id, slot.phan_mon_id, ppct
            )
            if not ten_bai and not notes:
                notes = "Catalog chưa có tên bài cho PPCT này"
            return FillOp(
                tuan=tuan,
                row_key=row_key,
                lop_id=slot.lop_id,
                lop_text=slot.lop_text,
                mon_id=slot.mon_id,
                mon_text=slot.mon_text,
                phan_mon_id=slot.phan_mon_id,
                phan_mon_text=slot.phan_mon_text,
                ppct=ppct,
                ten_bai=ten_bai,
                source="catalog" if ten_bai and source == "tkb" else source,
                notes=notes,
                ghi_chu=ghi_chu,
                trang_thai=trang_thai,
            )

        row_keys = set(template_by_key) | set(day_bu_by_key)
        for row_key in sorted(row_keys, key=_slot_key_sort):
            day_bu_event = day_bu_by_key.get(row_key)
            if day_bu_event is not None:
                if row_key in template_by_key and not day_bu_event.replace_normal_slot:
                    raise ProfileSchemaError(
                        "NghiDayBu.day_bu_trung_tkb",
                        f"Tiết Dạy bù tuần {tuan}, thứ {day_bu_event.thu}, "
                        f"buổi {day_bu_event.buoi}, tiết {day_bu_event.tiet} "
                        "đang trùng ô TKB thường nhưng chưa được xác nhận ghi đè.",
                    )
                source_slot = day_bu_event.to_slot_at_target()
                group_key = day_bu_event.group_key
                ppct = progress_by_group.get(group_key, 1)
                note = day_bu_event.note or "Dạy bù"
                notes = "Dạy bù: PPCT được tính tiếp và tăng sau tiết này"
                if row_key in template_by_key:
                    notes += "; vị trí này dùng cho tiết bù thay tiết TKB thường"
                wp.fill_ops.append(_make_op(
                    slot=source_slot,
                    row_key=row_key,
                    ppct=ppct,
                    trang_thai=TT_DAY_BU,
                    ghi_chu=note,
                    notes=notes,
                    source="tkb_day_bu",
                ))
                progress_by_group[group_key] = ppct + 1
                continue

            slot = template_by_key.get(row_key)
            if slot is None:
                continue
            group_key = slot.group_key
            ppct = progress_by_group.get(group_key, 1)
            nghi_event = nghi_by_key.get(row_key)
            if nghi_event is not None:
                if not nghi_event.source_matches_slot(slot):
                    raise ProfileSchemaError(
                        "NghiDayBu.nghi_khong_khop",
                        f"Tiết Nghỉ tuần {tuan}, thứ {slot.thu}, buổi {slot.buoi}, "
                        f"tiết {slot.tiet} không còn đúng môn/lớp nguồn đã chọn.",
                    )
                wp.fill_ops.append(_make_op(
                    slot=slot,
                    row_key=row_key,
                    ppct=ppct,
                    trang_thai=TT_NGHI,
                    ghi_chu=nghi_event.note or "Nghỉ",
                    notes="Nghỉ: vẫn ghi PPCT nhưng không tăng số",
                    source="tkb_nghi",
                ))
                continue

            wp.fill_ops.append(_make_op(
                slot=slot,
                row_key=row_key,
                ppct=ppct,
                trang_thai=TT_BINH_THUONG,
            ))
            # Increment PPCT cho slot kế tiếp cùng group
            progress_by_group[group_key] = ppct + 1

        # Apply filter only_lop_ids / only_phan_mon_ids
        if request.only_lop_ids or request.only_phan_mon_ids:
            for op in wp.fill_ops:
                if request.only_lop_ids and op.lop_id not in request.only_lop_ids:
                    op.skip = True
                if (request.only_phan_mon_ids
                        and op.phan_mon_id not in request.only_phan_mon_ids):
                    op.skip = True

        wp.estimated_changes = sum(1 for op in wp.fill_ops if not op.skip)
        return wp

    def _lookup_ten_bai(self, lop_id: str, mon_id: str,
                        phan_mon_id: str, ppct: int) -> str:
        """Tìm tên bài trong catalog (nếu có). Trả "" nếu không có."""
        if self.catalog is None:
            return ""
        try:
            return self.catalog.lookup_with_fallback(
                lop_id, mon_id, phan_mon_id, ppct
            ) or ""
        except Exception:
            return ""

    def _plan_for_week(self, tuan: int, request: PlanRequest, report: PlanReport) -> WeekPlan:
        """Plan cho 1 tuần."""
        wp = WeekPlan(tuan=tuan, strategy=request.strategy)

        cur_data = self.weeks_data.get(tuan)
        if cur_data and request.skip_weeks_with_data:
            filled_count = len(cur_data.filled_slots)
            if filled_count >= request.skip_threshold:
                wp.skip_reason = f"Đã có {filled_count} slot, skip"
                return wp

        # Build expected slots cho tuần này
        # Dùng pattern tuần X-1 nếu có, fallback pattern hiện tại của report
        ref_pattern = self._find_reference_pattern(tuan)
        if ref_pattern is None:
            wp.skip_reason = "Không tìm được TKB pattern reference"
            return wp

        # ---- STRATEGY ----
        if request.strategy == PlanStrategy.GEN_FROM_PREV_WEEK:
            # Pre-action: gọi API gen từ tuần trước
            wp.pre_action = "gen_prev"
            wp.pre_action_args = {"tuan": tuan}
            # Sau khi gen, server sẽ copy đầy đủ. Nếu auto_skip_filled_after_gen=True
            # thì không cần fill thêm. Nếu user muốn override, sinh ops:
            if not request.auto_skip_filled_after_gen:
                wp.fill_ops = self._build_fill_ops_for_pattern(tuan, ref_pattern, request)

        elif request.strategy == PlanStrategy.GEN_FROM_TKB:
            wp.pre_action = "gen_tkb"
            wp.pre_action_args = {"tuan": tuan}
            # Gen từ TKB không có PPCT/ten_bai → cần fill
            wp.fill_ops = self._build_fill_ops_for_pattern(tuan, ref_pattern, request)

        elif request.strategy == PlanStrategy.FILL_FROM_SCRATCH:
            wp.fill_ops = self._build_fill_ops_for_pattern(tuan, ref_pattern, request)

        elif request.strategy == PlanStrategy.UPDATE_EMPTY_ONLY:
            # Chỉ điền slot đang trống
            if cur_data is None:
                wp.skip_reason = "Chưa scan tuần này — bỏ qua chế độ update_empty"
                return wp
            wp.fill_ops = self._build_fill_ops_for_empty_slots(tuan, cur_data, request)

        # Apply lọc only_lop_ids, only_phan_mon_ids
        if request.only_lop_ids or request.only_phan_mon_ids:
            for op in wp.fill_ops:
                if request.only_lop_ids and op.lop_id not in request.only_lop_ids:
                    op.skip = True
                if request.only_phan_mon_ids and op.phan_mon_id not in request.only_phan_mon_ids:
                    op.skip = True

        wp.estimated_changes = sum(1 for op in wp.fill_ops if not op.skip)
        return wp

    def _find_reference_pattern(self, tuan: int) -> YearTKBPattern | None:
        """Tìm pattern TKB phù hợp cho tuần này:
        1. Nếu tuan đã có pattern (đã từng có data) → dùng pattern đó
        2. Fallback: lấy pattern của tuần liền kề có data (tuần trước hoặc sau)
        """
        for p in self.report.patterns:
            if tuan in p.weeks:
                return p
        # Tìm tuần liền kề có pattern
        all_weeks_with_pattern = sorted(set(t for p in self.report.patterns for t in p.weeks))
        if not all_weeks_with_pattern:
            return None
        # Closest week
        closest = min(all_weeks_with_pattern, key=lambda t: abs(t - tuan))
        for p in self.report.patterns:
            if closest in p.weeks:
                return p
        return None

    def _build_fill_ops_for_pattern(
        self, tuan: int, pattern: YearTKBPattern, request: PlanRequest
    ) -> list[FillOp]:
        """Sinh ops dựa trên TKB pattern. PPCT cuốn chiếu từ progress."""
        ops: list[FillOp] = []
        # Để increment PPCT đúng, cần biết tuần này so với các tuần đã có data
        # → Chia theo (lop, mon, phan_mon) và giả định mỗi slot tuần = 1 PPCT
        # Sort slots theo (thu, buoi, tiet) — phần cứng để PPCT chạy
        slots_sorted = sorted(pattern.slots, key=lambda s: (s.thu, s.buoi_idx, s.tiet_idx))

        # Group theo (lop, mon) để increment PPCT đúng cho mỗi nhóm trong 1 tuần
        # Tính delta tuần: nếu có pattern data ở tuần khác, lấy mức PPCT đó + (tuan - tuan_đó) * slots/tuần
        # Đơn giản hơn: lấy progress.next_ppct và increment per slot trong tuần này

        # PPCT counter cho từng group trong tuần này
        group_counter: dict[str, int] = {}
        # Đầu tiên copy next_ppct từ progress (trừ đi 1 vì sẽ +1 ở slot đầu)
        for slot_key in slots_sorted:
            # Tìm phan_mon từ data hiện có (vì pattern không lưu phan_mon)
            phan_mon_id = self._guess_phan_mon_id(slot_key.lop_id, slot_key.mon_id)
            group = f"{slot_key.lop_id}|{slot_key.mon_id}|{phan_mon_id}"
            if group not in group_counter:
                # Tính next_ppct cho group này TẠI TUẦN tuan
                group_counter[group] = self._compute_starting_ppct(
                    slot_key.lop_id, slot_key.mon_id, phan_mon_id, tuan
                )
            ppct = group_counter[group]

            # Lookup tên bài từ catalog
            ten_bai = self.catalog.lookup_with_fallback(
                slot_key.lop_id, slot_key.mon_id, phan_mon_id, ppct
            ) or ""

            ops.append(FillOp(
                tuan=tuan,
                row_key=f"{slot_key.thu}_{slot_key.buoi_idx}_{slot_key.tiet_idx}",
                lop_id=slot_key.lop_id,
                mon_id=slot_key.mon_id,
                phan_mon_id=phan_mon_id,
                ppct=ppct,
                ten_bai=ten_bai,
                source="catalog" if ten_bai else "tkb",
                notes="" if ten_bai else "Catalog chưa có tên bài",
            ))
            group_counter[group] = ppct + 1
        return ops

    def _build_fill_ops_for_empty_slots(
        self, tuan: int, cur_data: WeekData, request: PlanRequest
    ) -> list[FillOp]:
        """Chỉ sinh ops cho slot có lop nhưng chưa có ppct/ten_bai."""
        ops: list[FillOp] = []
        empty_slots = [s for s in cur_data.tkb_slots if not s.is_filled]
        for slot in empty_slots:
            # Phan_mon hiện tại nếu đã có, còn không thì guess
            pm_id = slot.phan_mon_id
            if not pm_id or pm_id == "0":
                pm_id = self._guess_phan_mon_id(slot.lop_id, slot.mon_id)

            try:
                cur_ppct = int(slot.ppct) if slot.ppct else 0
            except ValueError:
                cur_ppct = 0
            ppct = cur_ppct if cur_ppct > 0 else self._compute_starting_ppct(
                slot.lop_id, slot.mon_id, pm_id, tuan
            )
            ten_bai = slot.ten_bai or self.catalog.lookup_with_fallback(
                slot.lop_id, slot.mon_id, pm_id, ppct
            ) or ""

            ops.append(FillOp(
                tuan=tuan, row_key=slot.row_key,
                lop_id=slot.lop_id, mon_id=slot.mon_id,
                phan_mon_id=pm_id, ppct=ppct, ten_bai=ten_bai,
                source="catalog" if ten_bai else "tkb",
                notes="" if ten_bai else "Catalog chưa có tên bài",
            ))
        return ops

    # -----------------------------------------------------------
    # Helpers
    # -----------------------------------------------------------

    def _guess_phan_mon_id(self, lop_id: str, mon_id: str) -> str:
        """Đoán phan_mon_id thường dùng cho (lop, mon) — tìm từ progress."""
        # Group theo lop/mon, lấy phan_mon được dùng nhiều nhất
        best_pm = ""
        best_count = 0
        for key, p in self.report.subject_progress.items():
            if p.lop_id == lop_id and p.mon_id == mon_id:
                cnt = len(p.ppct_history)
                if cnt > best_count:
                    best_count = cnt
                    best_pm = p.phan_mon_id
        return best_pm

    def _compute_starting_ppct(
        self, lop_id: str, mon_id: str, phan_mon_id: str, target_tuan: int
    ) -> int:
        """Tính PPCT bắt đầu cho group (lop, mon, pm) tại target_tuan.

        Priority order (v2.1 — profile-first, scan chỉ là backup):
          1. Profile ppct_starts: TUYỆT ĐỐI tôn trọng config tay của user.
             User có thể tính bù khoảng trống cho tuần nghỉ → đặt PPCT lớn hơn
             max trên web. Tool KHÔNG ĐƯỢC tự ý đoán.
          2. Scan-based: chỉ dùng khi profile chưa có (group mới).
          3. Legacy report.subject_progress + delta tuần.
          4. Fallback 1.

        Lý do đảo priority (sửa bug v2): trước đây scan ưu tiên hơn profile,
        gây bug user setup PPCT 72 cho tuần 26 (đã tính bù) nhưng web max=62
        → tool override thành 63. Đây là source-of-truth bị đảo.
        """
        if not phan_mon_id:
            return 1
        key = f"{lop_id}|{mon_id}|{phan_mon_id}"

        # 1. Profile ppct_starts — ƯU TIÊN CAO NHẤT (config user tay)
        if self.profile is not None:
            try:
                start = self.profile.get_ppct_start(lop_id, mon_id, phan_mon_id)
                if start and start > 0:
                    return start
            except Exception:
                pass

        # 2. Scan-based — fallback nếu profile chưa có group này
        scan_progress = self._scan_cache.get(target_tuan)
        if scan_progress is not None:
            sp = scan_progress.get(key)
            if sp is not None and sp.last_ppct > 0:
                return sp.last_ppct + 1

        # 3. Legacy: report.subject_progress + delta
        if self.report is None:
            return 1
        p = self.report.subject_progress.get(key)
        if not p or not p.ppct_history:
            return 1
        if target_tuan <= p.last_tuan:
            return p.next_ppct
        weeks_count = max(1, len({t for t, _, _ in p.ppct_history}))
        ppct_count = len(p.ppct_history)
        slots_per_week = max(1, ppct_count // weeks_count) if ppct_count > 0 else 1
        delta = target_tuan - p.last_tuan
        return p.last_ppct + 1 + (delta - 1) * slots_per_week

    # -----------------------------------------------------------
    # v2: Scan-before-fill helpers
    # -----------------------------------------------------------

    def _scan_progress_up_to(self, target_tuan: int,
                             tuan_from: int = 1) -> dict[str, "SubjectProgress"]:
        """Scan web cho mọi tuần [tuan_from..target_tuan-1] → compute progress.

        Idempotent + cached: nếu đã có `_scan_cache[target_tuan]` → return.

        Return: dict[group_key, SubjectProgress] đã filter theo TT_COUNTED và
        track extras qua `compute_progress`. Nếu không có client → return {}.

        Errors khi fetch_week được swallow (log warning) để 1 tuần fail không
        block toàn plan — fallback sang legacy logic ở `_compute_starting_ppct`.
        """
        if target_tuan in self._scan_cache:
            return self._scan_cache[target_tuan]
        if self.client is None:
            self._scan_cache[target_tuan] = {}
            return {}

        scanned: dict[int, WeekData] = {}
        for t in range(tuan_from, target_tuan):
            if t in self._fetched_weeks:
                scanned[t] = self._fetched_weeks[t]
                continue
            try:
                wd = self.client.fetch_week(t)
                if wd is not None:
                    scanned[t] = wd
                    self._fetched_weeks[t] = wd
            except Exception as e:
                logger.warning("scan tuần %s failed: %s", t, e)
                continue

        progress = PatternAnalyzer.compute_progress(scanned)
        self._scan_cache[target_tuan] = progress
        return progress


# ######################################################################
# Section: profile
# ######################################################################



# =====================================================================
# Constants
# =====================================================================

# Thứ trong tuần: 2..7 + 8 (CN). Khớp convention của VnEdu.
ALLOWED_THU = (2, 3, 4, 5, 6, 7, 8)
ALLOWED_BUOI = (1, 2)        # 1=Sáng, 2=Chiều
ALLOWED_TIET = (1, 2, 3, 4, 5)


# =====================================================================
# Exception
# =====================================================================

class ProfileSchemaError(Exception):
    """Hồ sơ Excel/dữ liệu sai cấu trúc.

    Attributes:
        field: tên field/cell/sheet bị lỗi (vd "TKB lẻ.row3.Lớp")
        msg:   mô tả lỗi tiếng Việt cho giáo viên đọc
    """

    def __init__(self, field: str, msg: str):
        self.field = field
        self.msg = msg
        super().__init__(f"[{field}] {msg}")


# =====================================================================
# SlotEntry — 1 tiết trong TKB
# =====================================================================

@dataclass
class SlotEntry:
    """1 tiết được giáo viên dạy trong tuần (mẫu TKB).

    Identity = (thu, buoi, tiet). Slot ở cùng vị trí trong 2 mẫu lẻ/chẵn
    là 2 SlotEntry độc lập (không share).
    """
    thu: int                 # 2..8 (8 = CN)
    buoi: int                # 1=Sáng, 2=Chiều
    tiet: int                # 1..5
    lop_id: str
    lop_text: str
    mon_id: str
    mon_text: str
    phan_mon_id: str
    phan_mon_text: str

    def __post_init__(self):
        if self.thu not in ALLOWED_THU:
            raise ProfileSchemaError(
                f"SlotEntry.thu",
                f"Thứ phải là 2-7 hoặc 8 (CN). Nhận: {self.thu!r}",
            )
        if self.buoi not in ALLOWED_BUOI:
            raise ProfileSchemaError(
                f"SlotEntry.buoi",
                f"Buổi phải là 1 (Sáng) hoặc 2 (Chiều). Nhận: {self.buoi!r}",
            )
        if self.tiet not in ALLOWED_TIET:
            raise ProfileSchemaError(
                f"SlotEntry.tiet",
                f"Tiết phải từ 1 đến 5. Nhận: {self.tiet!r}",
            )
        # Validate ID không rỗng / không là "0"
        for fname in ("lop_id", "mon_id", "phan_mon_id"):
            v = getattr(self, fname)
            if not v or str(v).strip() == "" or str(v).strip() == "0":
                raise ProfileSchemaError(
                    f"SlotEntry.{fname}",
                    f"Trường '{fname}' không được để trống hoặc bằng 0. "
                    f"Slot Thứ {self.thu} - Buổi {self.buoi} - Tiết {self.tiet}.",
                )
        # Strip text fields
        self.lop_text = (self.lop_text or "").strip()
        self.mon_text = (self.mon_text or "").strip()
        self.phan_mon_text = (self.phan_mon_text or "").strip()

    @property
    def slot_key(self) -> str:
        """Key duy nhất theo vị trí — `thu_buoi_tiet`."""
        return f"{self.thu}_{self.buoi}_{self.tiet}"

    @property
    def buoi_text(self) -> str:
        return "Sáng" if self.buoi == 1 else "Chiều"

    @property
    def thu_text(self) -> str:
        return "CN" if self.thu == 8 else f"Thứ {self.thu}"

    @property
    def group_key(self) -> str:
        """Key nhóm (lop, mon, phan_mon) — dùng để cuốn chiếu PPCT."""
        return f"{self.lop_id}|{self.mon_id}|{self.phan_mon_id}"


# =====================================================================
# TKBHolidayRule — quy tắc Nghỉ / Dạy bù cho hồ sơ TKB
# =====================================================================

@dataclass
class TKBHolidayRule:
    """1 quy tắc đánh dấu một tiết Nghỉ và tùy chọn một tiết Dạy bù."""
    holiday_tuan: int
    holiday_thu: int
    holiday_buoi: int
    holiday_tiet: int
    makeup_tuan: int = 0
    makeup_thu: int = 0
    makeup_buoi: int = 0
    makeup_tiet: int = 0
    note: str = ""
    enabled: bool = True

    def __post_init__(self):
        for field_name in ("holiday_tuan", "holiday_thu", "holiday_buoi",
                           "holiday_tiet", "makeup_tuan", "makeup_thu",
                           "makeup_buoi", "makeup_tiet"):
            value = getattr(self, field_name)
            try:
                setattr(self, field_name, int(value or 0))
            except (TypeError, ValueError):
                raise ProfileSchemaError(
                    f"TKBHolidayRule.{field_name}",
                    f"Giá trị phải là số nguyên. Nhận: {value!r}",
                )

        if not (1 <= self.holiday_tuan <= 52):
            raise ProfileSchemaError(
                "TKBHolidayRule.holiday_tuan",
                f"Tuần nghỉ phải từ 1 đến 52. Nhận: {self.holiday_tuan}",
            )
        if self.holiday_thu not in ALLOWED_THU:
            raise ProfileSchemaError(
                "TKBHolidayRule.holiday_thu",
                f"Thứ nghỉ phải là 2-7 hoặc 8 (CN). Nhận: {self.holiday_thu}",
            )
        if self.holiday_buoi not in ALLOWED_BUOI:
            raise ProfileSchemaError(
                "TKBHolidayRule.holiday_buoi",
                f"Buổi nghỉ phải là 1 (Sáng) hoặc 2 (Chiều). Nhận: {self.holiday_buoi}",
            )
        if self.holiday_tiet not in ALLOWED_TIET:
            raise ProfileSchemaError(
                "TKBHolidayRule.holiday_tiet",
                f"Tiết nghỉ phải từ 1 đến 5. Nhận: {self.holiday_tiet}",
            )

        has_any_makeup = any((
            self.makeup_tuan, self.makeup_thu,
            self.makeup_buoi, self.makeup_tiet,
        ))
        if has_any_makeup and not self.has_makeup:
            raise ProfileSchemaError(
                "TKBHolidayRule.makeup",
                "Nếu có dạy bù thì phải nhập đủ tuần, thứ, buổi và tiết bù.",
            )
        if self.has_makeup:
            if not (1 <= self.makeup_tuan <= 52):
                raise ProfileSchemaError(
                    "TKBHolidayRule.makeup_tuan",
                    f"Tuần bù phải từ 1 đến 52. Nhận: {self.makeup_tuan}",
                )
            if self.makeup_thu not in ALLOWED_THU:
                raise ProfileSchemaError(
                    "TKBHolidayRule.makeup_thu",
                    f"Thứ bù phải là 2-7 hoặc 8 (CN). Nhận: {self.makeup_thu}",
                )
            if self.makeup_buoi not in ALLOWED_BUOI:
                raise ProfileSchemaError(
                    "TKBHolidayRule.makeup_buoi",
                    f"Buổi bù phải là 1 (Sáng) hoặc 2 (Chiều). Nhận: {self.makeup_buoi}",
                )
            if self.makeup_tiet not in ALLOWED_TIET:
                raise ProfileSchemaError(
                    "TKBHolidayRule.makeup_tiet",
                    f"Tiết bù phải từ 1 đến 5. Nhận: {self.makeup_tiet}",
                )
        self.note = (self.note or "").strip()
        self.enabled = bool(self.enabled)

    @property
    def holiday_slot_key(self) -> str:
        return f"{self.holiday_thu}_{self.holiday_buoi}_{self.holiday_tiet}"

    @property
    def makeup_slot_key(self) -> str:
        if not self.has_makeup:
            return ""
        return f"{self.makeup_thu}_{self.makeup_buoi}_{self.makeup_tiet}"

    @property
    def has_makeup(self) -> bool:
        return all((
            self.makeup_tuan > 0,
            self.makeup_thu > 0,
            self.makeup_buoi > 0,
            self.makeup_tiet > 0,
        ))

    def clone(self) -> "TKBHolidayRule":
        return TKBHolidayRule(
            holiday_tuan=self.holiday_tuan,
            holiday_thu=self.holiday_thu,
            holiday_buoi=self.holiday_buoi,
            holiday_tiet=self.holiday_tiet,
            makeup_tuan=self.makeup_tuan,
            makeup_thu=self.makeup_thu,
            makeup_buoi=self.makeup_buoi,
            makeup_tiet=self.makeup_tiet,
            note=self.note,
            enabled=self.enabled,
        )

    def holiday_position_tuple(self) -> tuple[int, int, int, int]:
        return (
            self.holiday_tuan, self.holiday_thu,
            self.holiday_buoi, self.holiday_tiet,
        )

    def makeup_position_tuple(self) -> tuple[int, int, int, int] | None:
        if not self.has_makeup:
            return None
        return (
            self.makeup_tuan, self.makeup_thu,
            self.makeup_buoi, self.makeup_tiet,
        )

# =====================================================================
# TKBScheduleEvent — sự kiện Nghỉ / Dạy bù độc lập
# =====================================================================

@dataclass
class TKBScheduleEvent:
    """Một lần áp dụng Nghỉ hoặc Dạy bù tại đúng tuần/thứ/buổi/tiết.

    Khác `TKBHolidayRule` cũ, mỗi event đứng độc lập. Nhờ vậy một tiết
    Nghỉ không tự ép phải có một tiết Dạy bù kèm theo, và một môn có thể
    có nhiều tiết Dạy bù ở các tuần sau để bù đủ PPCT.
    """
    kind: str
    tuan: int
    thu: int
    buoi: int
    tiet: int
    source_lop_id: str
    source_lop_text: str
    source_mon_id: str
    source_mon_text: str
    source_phan_mon_id: str
    source_phan_mon_text: str
    source_slot_key: str = ""
    note: str = ""
    enabled: bool = True
    replace_normal_slot: bool = False

    def __post_init__(self):
        self.kind = str(self.kind or "").strip().lower()
        if self.kind not in (TKB_EVENT_NGHI, TKB_EVENT_DAY_BU):
            raise ProfileSchemaError(
                "TKBScheduleEvent.kind",
                "Loại sự kiện phải là 'Nghỉ' hoặc 'Dạy bù'.",
            )
        for field_name in ("tuan", "thu", "buoi", "tiet"):
            value = getattr(self, field_name)
            try:
                setattr(self, field_name, int(value or 0))
            except (TypeError, ValueError):
                raise ProfileSchemaError(
                    f"TKBScheduleEvent.{field_name}",
                    f"Giá trị phải là số nguyên. Nhận: {value!r}",
                )
        if not (1 <= self.tuan <= 52):
            raise ProfileSchemaError(
                "TKBScheduleEvent.tuan",
                f"Tuần phải từ 1 đến 52. Nhận: {self.tuan}",
            )
        if self.thu not in ALLOWED_THU:
            raise ProfileSchemaError(
                "TKBScheduleEvent.thu",
                f"Thứ phải là 2-7 hoặc 8 (CN). Nhận: {self.thu}",
            )
        if self.buoi not in ALLOWED_BUOI:
            raise ProfileSchemaError(
                "TKBScheduleEvent.buoi",
                f"Buổi phải là 1 (Sáng) hoặc 2 (Chiều). Nhận: {self.buoi}",
            )
        if self.tiet not in ALLOWED_TIET:
            raise ProfileSchemaError(
                "TKBScheduleEvent.tiet",
                f"Tiết phải từ 1 đến 5. Nhận: {self.tiet}",
            )
        for fname in ("source_lop_id", "source_mon_id", "source_phan_mon_id"):
            value = str(getattr(self, fname) or "").strip()
            if not value or value == "0":
                raise ProfileSchemaError(
                    f"TKBScheduleEvent.{fname}",
                    "Thông tin lớp/môn/phân môn nguồn không được để trống.",
                )
            setattr(self, fname, value)
        self.source_lop_text = str(self.source_lop_text or "").strip()
        self.source_mon_text = str(self.source_mon_text or "").strip()
        self.source_phan_mon_text = str(self.source_phan_mon_text or "").strip()
        self.source_slot_key = str(self.source_slot_key or "").strip()
        self.note = str(self.note or "").strip()
        self.enabled = bool(self.enabled)
        self.replace_normal_slot = bool(self.replace_normal_slot)

    @property
    def row_key(self) -> str:
        return f"{self.thu}_{self.buoi}_{self.tiet}"

    @property
    def group_key(self) -> str:
        return (
            f"{self.source_lop_id}|{self.source_mon_id}|"
            f"{self.source_phan_mon_id}"
        )

    @property
    def label(self) -> str:
        return TKB_EVENT_LABELS.get(self.kind, self.kind)

    def position_tuple(self) -> tuple[int, int, int, int]:
        return self.tuan, self.thu, self.buoi, self.tiet

    def source_matches_slot(self, slot: "SlotEntry | None") -> bool:
        if slot is None:
            return False
        return (
            slot.lop_id == self.source_lop_id
            and slot.mon_id == self.source_mon_id
            and slot.phan_mon_id == self.source_phan_mon_id
        )

    def to_slot_at_target(self) -> "SlotEntry":
        return SlotEntry(
            thu=self.thu,
            buoi=self.buoi,
            tiet=self.tiet,
            lop_id=self.source_lop_id,
            lop_text=self.source_lop_text,
            mon_id=self.source_mon_id,
            mon_text=self.source_mon_text,
            phan_mon_id=self.source_phan_mon_id,
            phan_mon_text=self.source_phan_mon_text,
        )

    def clone(self) -> "TKBScheduleEvent":
        return TKBScheduleEvent(
            kind=self.kind,
            tuan=self.tuan,
            thu=self.thu,
            buoi=self.buoi,
            tiet=self.tiet,
            source_lop_id=self.source_lop_id,
            source_lop_text=self.source_lop_text,
            source_mon_id=self.source_mon_id,
            source_mon_text=self.source_mon_text,
            source_phan_mon_id=self.source_phan_mon_id,
            source_phan_mon_text=self.source_phan_mon_text,
            source_slot_key=self.source_slot_key,
            note=self.note,
            enabled=self.enabled,
            replace_normal_slot=self.replace_normal_slot,
        )

    @classmethod
    def from_slot(
        cls,
        *,
        kind: str,
        source_slot: "SlotEntry",
        tuan: int,
        thu: int,
        buoi: int,
        tiet: int,
        note: str = "",
        enabled: bool = True,
        replace_normal_slot: bool = False,
    ) -> "TKBScheduleEvent":
        return cls(
            kind=kind,
            tuan=tuan,
            thu=thu,
            buoi=buoi,
            tiet=tiet,
            source_lop_id=source_slot.lop_id,
            source_lop_text=source_slot.lop_text,
            source_mon_id=source_slot.mon_id,
            source_mon_text=source_slot.mon_text,
            source_phan_mon_id=source_slot.phan_mon_id,
            source_phan_mon_text=source_slot.phan_mon_text,
            source_slot_key=source_slot.slot_key,
            note=note,
            enabled=enabled,
            replace_normal_slot=replace_normal_slot,
        )

# =====================================================================
# TKBTemplate — 1 mẫu TKB (chính / lẻ / chẵn)
# =====================================================================

@dataclass
class TKBTemplate:
    """1 mẫu TKB: tập hợp các SlotEntry."""
    slots: list[SlotEntry] = field(default_factory=list)

    def slot_at(self, thu: int, buoi: int, tiet: int) -> SlotEntry | None:
        for s in self.slots:
            if s.thu == thu and s.buoi == buoi and s.tiet == tiet:
                return s
        return None

    def all_groups(self) -> list[tuple[str, str, str]]:
        """Trả các (lop_id, mon_id, phan_mon_id) duy nhất, ổn định thứ tự."""
        seen: set[tuple[str, str, str]] = set()
        out: list[tuple[str, str, str]] = []
        for s in self.slots:
            key = (s.lop_id, s.mon_id, s.phan_mon_id)
            if key not in seen:
                seen.add(key)
                out.append(key)
        return out

    def all_groups_with_text(self) -> list[dict[str, str]]:
        """Trả groups kèm text label, ổn định thứ tự xuất hiện."""
        seen: set[tuple[str, str, str]] = set()
        out: list[dict[str, str]] = []
        for s in self.slots:
            key = (s.lop_id, s.mon_id, s.phan_mon_id)
            if key not in seen:
                seen.add(key)
                out.append({
                    "lop_id": s.lop_id, "lop_text": s.lop_text,
                    "mon_id": s.mon_id, "mon_text": s.mon_text,
                    "phan_mon_id": s.phan_mon_id, "phan_mon_text": s.phan_mon_text,
                })
        return out

    def slot_count(self) -> int:
        return len(self.slots)

    def slot_count_by_group(self) -> dict[str, int]:
        """Số slot mỗi group_key — dùng cho cuốn chiếu PPCT giữa 2 mẫu."""
        out: dict[str, int] = {}
        for s in self.slots:
            out[s.group_key] = out.get(s.group_key, 0) + 1
        return out

    def upsert_slot(self, slot: SlotEntry) -> None:
        """Insert hoặc replace slot tại (thu, buoi, tiet)."""
        for i, existing in enumerate(self.slots):
            if (existing.thu == slot.thu and existing.buoi == slot.buoi
                    and existing.tiet == slot.tiet):
                self.slots[i] = slot
                return
        self.slots.append(slot)

    def delete_slot(self, thu: int, buoi: int, tiet: int) -> bool:
        """Xóa slot tại vị trí. Trả True nếu có xóa."""
        for i, s in enumerate(self.slots):
            if s.thu == thu and s.buoi == buoi and s.tiet == tiet:
                del self.slots[i]
                return True
        return False

    def clone(self) -> "TKBTemplate":
        """Deep copy template."""
        new_slots = [
            SlotEntry(
                thu=s.thu, buoi=s.buoi, tiet=s.tiet,
                lop_id=s.lop_id, lop_text=s.lop_text,
                mon_id=s.mon_id, mon_text=s.mon_text,
                phan_mon_id=s.phan_mon_id, phan_mon_text=s.phan_mon_text,
            )
            for s in self.slots
        ]
        return TKBTemplate(slots=new_slots)

    def __eq__(self, other: object) -> bool:
        """So sánh 2 mẫu — dùng để cảnh báo Requirement 2.3.

        2 mẫu equal khi tập slot identity giống nhau VÀ data slot giống nhau.
        Bỏ qua thứ tự `slots` list.
        """
        if not isinstance(other, TKBTemplate):
            return NotImplemented
        return self._fingerprint() == other._fingerprint()

    def __hash__(self):
        return hash(self._fingerprint())

    def _fingerprint(self) -> frozenset[tuple]:
        """Tuple bất biến đại diện slot → dùng cho hash/eq."""
        return frozenset(
            (s.thu, s.buoi, s.tiet, s.lop_id, s.mon_id, s.phan_mon_id)
            for s in self.slots
        )

    def has_slot_at(self, thu: int, buoi: int, tiet: int) -> bool:
        return self.slot_at(thu, buoi, tiet) is not None


# =====================================================================
# PPCTStartEntry — PPCT bắt đầu cho 1 nhóm (lớp × phân môn)
# =====================================================================

@dataclass
class PPCTStartEntry:
    """PPCT bắt đầu của 1 nhóm trong tuần `tuan_from`.

    PPCT của tuần kế = ppct_start + tổng số slot của nhóm đó từ tuần đầu
    đến trước tuần kế.
    """
    lop_id: str
    lop_text: str
    mon_id: str
    mon_text: str
    phan_mon_id: str
    phan_mon_text: str
    ppct_start: int = 1
    ghi_chu: str = ""

    def __post_init__(self):
        for fname in ("lop_id", "mon_id", "phan_mon_id"):
            v = getattr(self, fname)
            if not v or str(v).strip() == "" or str(v).strip() == "0":
                raise ProfileSchemaError(
                    f"PPCTStartEntry.{fname}",
                    f"Trường '{fname}' không được để trống hoặc 0.",
                )
        # Coerce int + validate ≥ 1
        try:
            self.ppct_start = int(self.ppct_start)
        except (TypeError, ValueError):
            raise ProfileSchemaError(
                "PPCTStartEntry.ppct_start",
                f"PPCT bắt đầu phải là số nguyên. Nhận: {self.ppct_start!r}",
            )
        if self.ppct_start < 1:
            raise ProfileSchemaError(
                "PPCTStartEntry.ppct_start",
                f"PPCT bắt đầu phải >= 1. Nhận: {self.ppct_start}",
            )
        self.lop_text = (self.lop_text or "").strip()
        self.mon_text = (self.mon_text or "").strip()
        self.phan_mon_text = (self.phan_mon_text or "").strip()
        self.ghi_chu = (self.ghi_chu or "").strip()

    @property
    def group_key(self) -> str:
        return f"{self.lop_id}|{self.mon_id}|{self.phan_mon_id}"


# =====================================================================
# KHDHProfile — toàn bộ hồ sơ
# =====================================================================

@dataclass
class KHDHProfile:
    """Toàn bộ hồ sơ KHDH — load từ Excel hoặc khởi tạo mới."""

    # === ThongTin ===
    ho_ten_gv: str
    nam_hoc: int                 # 2025 nghĩa là năm 2025-2026
    cap_hoc: int                 # 1=TH, 2=THCS, 3=THPT
    cap_hoc_text: str = ""       # "THCS"
    ma_truong: str = ""
    ngay_tao: str = ""           # ISO date
    ghi_chu: str = ""

    # === TKB ===
    tach_le_chan: bool = False
    template_chinh: TKBTemplate | None = None     # khi tach_le_chan=False
    template_le: TKBTemplate | None = None        # khi tach_le_chan=True
    template_chan: TKBTemplate | None = None      # khi tach_le_chan=True

    # === PPCT ===
    ppct_starts: list[PPCTStartEntry] = field(default_factory=list)

    # === Nghỉ / Dạy bù ===
    holiday_rules: list[TKBHolidayRule] = field(default_factory=list)
    schedule_events: list[TKBScheduleEvent] = field(default_factory=list)

    # === Dải tuần áp dụng ===
    tuan_from: int = 1
    tuan_to: int = 35

    # ----------------------------------------------------------
    # Validation
    # ----------------------------------------------------------

    def __post_init__(self):
        # ho_ten_gv
        if not self.ho_ten_gv or not self.ho_ten_gv.strip():
            raise ProfileSchemaError(
                "ThongTin.ho_ten_gv",
                "Họ tên giáo viên không được để trống.",
            )
        self.ho_ten_gv = self.ho_ten_gv.strip()

        # nam_hoc
        try:
            self.nam_hoc = int(self.nam_hoc)
        except (TypeError, ValueError):
            raise ProfileSchemaError(
                "ThongTin.nam_hoc",
                f"Năm học phải là số (vd 2025). Nhận: {self.nam_hoc!r}",
            )
        if not (2000 <= self.nam_hoc <= 2100):
            raise ProfileSchemaError(
                "ThongTin.nam_hoc",
                f"Năm học không hợp lệ: {self.nam_hoc}. Phải trong khoảng 2000-2100.",
            )

        # cap_hoc
        try:
            self.cap_hoc = int(self.cap_hoc)
        except (TypeError, ValueError):
            raise ProfileSchemaError(
                "ThongTin.cap_hoc",
                f"Cấp học phải là số (1=TH, 2=THCS, 3=THPT). Nhận: {self.cap_hoc!r}",
            )
        if self.cap_hoc not in (1, 2, 3):
            raise ProfileSchemaError(
                "ThongTin.cap_hoc",
                f"Cấp học phải là 1 (TH), 2 (THCS), hoặc 3 (THPT). Nhận: {self.cap_hoc}",
            )

        # tach_le_chan invariant
        if self.tach_le_chan:
            if self.template_chinh is not None:
                raise ProfileSchemaError(
                    "TKB.tach_le_chan",
                    "Đã tích 'tách lẻ/chẵn' nhưng vẫn có TKB chính. "
                    "Phải có TKB lẻ + TKB chẵn (không có TKB chính).",
                )
            if self.template_le is None or self.template_chan is None:
                raise ProfileSchemaError(
                    "TKB.tach_le_chan",
                    "Đã tích 'tách lẻ/chẵn' nhưng thiếu TKB lẻ hoặc TKB chẵn.",
                )
        else:
            if self.template_le is not None or self.template_chan is not None:
                raise ProfileSchemaError(
                    "TKB.tach_le_chan",
                    "Chưa tích 'tách lẻ/chẵn' nhưng có TKB lẻ/chẵn. "
                    "Phải có TKB chính (không có lẻ/chẵn).",
                )
            # Nếu chưa có template_chinh, tạo rỗng (giáo viên sẽ điền sau)
            if self.template_chinh is None:
                self.template_chinh = TKBTemplate(slots=[])

        # tuan_from / tuan_to
        try:
            self.tuan_from = int(self.tuan_from)
            self.tuan_to = int(self.tuan_to)
        except (TypeError, ValueError):
            raise ProfileSchemaError(
                "TuanRange",
                f"Tuần phải là số. Nhận: from={self.tuan_from!r}, to={self.tuan_to!r}",
            )
        if not (1 <= self.tuan_from <= 52):
            raise ProfileSchemaError(
                "TuanRange.tuan_from",
                f"Tuần bắt đầu phải từ 1 đến 52. Nhận: {self.tuan_from}",
            )
        if not (1 <= self.tuan_to <= 52):
            raise ProfileSchemaError(
                "TuanRange.tuan_to",
                f"Tuần kết thúc phải từ 1 đến 52. Nhận: {self.tuan_to}",
            )
        if self.tuan_from > self.tuan_to:
            raise ProfileSchemaError(
                "TuanRange",
                f"Tuần bắt đầu ({self.tuan_from}) phải <= Tuần kết thúc ({self.tuan_to}).",
            )

        # holiday_rules forward-compatible: file cũ không có sheet này → [].
        clean_rules: list[TKBHolidayRule] = []
        for idx, rule in enumerate(self.holiday_rules or [], 1):
            if isinstance(rule, TKBHolidayRule):
                clean_rules.append(rule)
                continue
            if isinstance(rule, dict):
                try:
                    clean_rules.append(TKBHolidayRule(**rule))
                    continue
                except ProfileSchemaError as e:
                    raise ProfileSchemaError(
                        f"NghiDayBu.row{idx}",
                        e.msg,
                    )
            raise ProfileSchemaError(
                f"NghiDayBu.row{idx}",
                "Quy tắc nghỉ/dạy bù không đúng cấu trúc.",
            )
        self.holiday_rules = clean_rules

        # schedule_events là model mới. Nếu hồ sơ cũ chỉ có holiday_rules,
        # chuyển được quy tắc nào thì đưa sang event để planner dùng chung.
        clean_events: list[TKBScheduleEvent] = []
        for idx, event in enumerate(self.schedule_events or [], 1):
            if isinstance(event, TKBScheduleEvent):
                clean_events.append(event)
                continue
            if isinstance(event, dict):
                try:
                    clean_events.append(TKBScheduleEvent(**event))
                    continue
                except ProfileSchemaError as e:
                    raise ProfileSchemaError(
                        f"NghiDayBu.event{idx}",
                        e.msg,
                    )
            raise ProfileSchemaError(
                f"NghiDayBu.event{idx}",
                "Sự kiện Nghỉ/Dạy bù không đúng cấu trúc.",
            )
        if clean_events:
            self.schedule_events = clean_events
        else:
            self.schedule_events = _legacy_holiday_rules_to_events(
                self, clean_rules, skip_invalid=True
            )

    # ----------------------------------------------------------
    # Public helpers
    # ----------------------------------------------------------

    @staticmethod
    def is_chan(tuan: int) -> bool:
        """Phân loại tuần chẵn/lẻ theo chữ số CUỐI của số tuần.

        - 0, 2, 4, 6, 8 → True (chẵn)
        - 1, 3, 5, 7, 9 → False (lẻ)

        Ví dụ:
            is_chan(10) → True (cuối là 0)
            is_chan(11) → False (cuối là 1)
            is_chan(22) → True
        """
        last_digit = abs(int(tuan)) % 10
        return last_digit % 2 == 0

    @staticmethod
    def is_le(tuan: int) -> bool:
        return not KHDHProfile.is_chan(tuan)

    def get_active_template(self, tuan: int) -> TKBTemplate:
        """Trả về template phù hợp cho tuần `tuan`.

        - tach_le_chan=False → luôn template_chinh
        - tach_le_chan=True  → template_le hoặc template_chan theo `is_chan`
        """
        if not self.tach_le_chan:
            assert self.template_chinh is not None
            return self.template_chinh
        if self.is_chan(tuan):
            assert self.template_chan is not None
            return self.template_chan
        assert self.template_le is not None
        return self.template_le

    def all_templates(self) -> list[TKBTemplate]:
        """Trả tất cả template không None — dùng cho validation chung."""
        out = []
        for t in (self.template_chinh, self.template_le, self.template_chan):
            if t is not None:
                out.append(t)
        return out

    def auto_compute_hdtn_chu_de_starts(
        self, tuan_from: int | None = None
    ) -> list[dict]:
        """Tính PPCT bắt đầu cho group HĐTN-Chủ-đề dựa trên tuan_from + tiết/tuần.

        Logic:
          - Cho mỗi group có (mon HĐTN + phân môn 'theo chủ đề'):
            • Đếm số tiết/tuần lẻ + tiết/tuần chẵn từ template
            • Số tiết PPCT đã dạy bởi GV trước (1..tuan_from-1):
                = sum_le_weeks * tiet_per_le_week + sum_chan_weeks * tiet_per_chan_week
              trong đó sum_le_weeks = số tuần lẻ trong [1..tuan_from-1]
                       sum_chan_weeks = số tuần chẵn tương tự
            • PPCT_start cho user (bắt đầu tuần tuan_from) = total + 1

        Args:
            tuan_from: tuần user bắt đầu dạy. Mặc định self.tuan_from.

        Returns:
            list[dict] — mỗi item:
              {group_key, lop_id, lop_text, mon_id, mon_text,
               phan_mon_id, phan_mon_text, tiet_le, tiet_chan,
               weeks_before_le, weeks_before_chan, total_before, suggested_ppct,
               current_ppct}
            Empty list nếu không tìm group nào.
        """
        if tuan_from is None:
            tuan_from = self.tuan_from
        if tuan_from is None or tuan_from <= 1:
            # Tuần 1 → GV trước không dạy gì → suggest 1 cho mọi group
            tuan_from = max(1, tuan_from or 1)

        # Tính tiết/tuần cho mỗi group ở template lẻ + chẵn
        # group_key → (tiet_le, tiet_chan, lop_text, mon_text, pm_text)
        per_group: dict[str, dict] = {}

        def _count_in_template(tmpl: TKBTemplate, slot_kind: str) -> None:
            """slot_kind: 'le', 'chan', or 'chinh'."""
            if tmpl is None:
                return
            for slot in tmpl.slots:
                if not is_hdtn_chu_de_group(slot.mon_text, slot.phan_mon_text):
                    continue
                gk = slot.group_key
                if gk not in per_group:
                    per_group[gk] = {
                        "group_key": gk,
                        "lop_id": slot.lop_id,
                        "lop_text": slot.lop_text,
                        "mon_id": slot.mon_id,
                        "mon_text": slot.mon_text,
                        "phan_mon_id": slot.phan_mon_id,
                        "phan_mon_text": slot.phan_mon_text,
                        "tiet_le": 0,
                        "tiet_chan": 0,
                    }
                if slot_kind == "le":
                    per_group[gk]["tiet_le"] += 1
                elif slot_kind == "chan":
                    per_group[gk]["tiet_chan"] += 1
                else:
                    # tach_le_chan=False → tiết áp cho cả lẻ và chẵn
                    per_group[gk]["tiet_le"] += 1
                    per_group[gk]["tiet_chan"] += 1

        if self.tach_le_chan:
            _count_in_template(self.template_le, "le")
            _count_in_template(self.template_chan, "chan")
        else:
            _count_in_template(self.template_chinh, "chinh")

        if not per_group:
            return []

        # Đếm số tuần lẻ + chẵn trong [1..tuan_from-1]
        weeks_before = list(range(1, tuan_from))
        weeks_le = sum(1 for t in weeks_before if not self.is_chan(t))
        weeks_chan = sum(1 for t in weeks_before if self.is_chan(t))

        # Build map current_ppct cho mỗi group (đọc từ ppct_starts hiện tại)
        cur_map: dict[str, int] = {
            e.group_key: e.ppct_start for e in self.ppct_starts
        }

        # Build kết quả
        results: list[dict] = []
        for gk, info in per_group.items():
            total_before = (weeks_le * info["tiet_le"]
                          + weeks_chan * info["tiet_chan"])
            suggested = total_before + 1
            results.append({
                **info,
                "weeks_before_le": weeks_le,
                "weeks_before_chan": weeks_chan,
                "total_before": total_before,
                "suggested_ppct": suggested,
                "current_ppct": cur_map.get(gk, 0),
            })
        # Sort theo (lop_text, phan_mon_text) cho UI
        results.sort(key=lambda x: (x["lop_text"], x["phan_mon_text"]))
        return results

    def all_groups_across_templates(self) -> list[dict[str, str]]:
        """Tổng hợp groups xuất hiện trong các template. Mỗi group hiện 1 lần."""
        seen: set[tuple[str, str, str]] = set()
        out: list[dict[str, str]] = []
        for tpl in self.all_templates():
            for g in tpl.all_groups_with_text():
                key = (g["lop_id"], g["mon_id"], g["phan_mon_id"])
                if key not in seen:
                    seen.add(key)
                    out.append(g)
        return out

    def sync_ppct_starts_with_templates(self) -> None:
        """Đảm bảo `ppct_starts` khớp với groups thực tế trong template:

        - Group có trong template nhưng chưa có entry → thêm với ppct_start=1
        - Group có entry nhưng không còn trong template → xóa
        - Giữ nguyên thứ tự + giá trị các entry còn hợp lệ
        """
        current_groups = self.all_groups_across_templates()
        current_keys = {(g["lop_id"], g["mon_id"], g["phan_mon_id"])
                       for g in current_groups}

        # 1) Bỏ entry không còn group
        self.ppct_starts = [
            e for e in self.ppct_starts
            if (e.lop_id, e.mon_id, e.phan_mon_id) in current_keys
        ]

        # 2) Thêm entry mới với ppct_start=1
        existing_keys = {(e.lop_id, e.mon_id, e.phan_mon_id) for e in self.ppct_starts}
        for g in current_groups:
            key = (g["lop_id"], g["mon_id"], g["phan_mon_id"])
            if key not in existing_keys:
                self.ppct_starts.append(PPCTStartEntry(
                    lop_id=g["lop_id"], lop_text=g["lop_text"],
                    mon_id=g["mon_id"], mon_text=g["mon_text"],
                    phan_mon_id=g["phan_mon_id"], phan_mon_text=g["phan_mon_text"],
                    ppct_start=1,
                ))

    def get_ppct_start(self, lop_id: str, mon_id: str, phan_mon_id: str) -> int:
        """Trả PPCT bắt đầu cho 1 group. Mặc định 1 nếu chưa cấu hình."""
        for e in self.ppct_starts:
            if (e.lop_id == lop_id and e.mon_id == mon_id
                    and e.phan_mon_id == phan_mon_id):
                return e.ppct_start
        return 1

    def templates_equal(self) -> bool:
        """True khi tach_le_chan=True và 2 template lẻ/chẵn giống y hệt nhau.

        Dùng cho cảnh báo Requirement 2.3.
        """
        if not self.tach_le_chan:
            return False
        return self.template_le == self.template_chan

    def toggle_tach_le_chan(self, on: bool, prefer: str = "le") -> None:
        """Bật/tắt chế độ tách lẻ/chẵn.

        Args:
            on: True để bật, False để tắt
            prefer: khi tắt — giữ "le" hay "chan" làm template_chinh

        Raises:
            ValueError: prefer không phải "le"/"chan"
        """
        if on and not self.tach_le_chan:
            # Bật: clone template_chinh thành 2 mẫu
            base = self.template_chinh.clone() if self.template_chinh else TKBTemplate()
            self.template_chan = base.clone()    # Mẫu gốc → chẵn
            self.template_le = base.clone()      # Bản clone → lẻ
            self.template_chinh = None
            self.tach_le_chan = True
        elif not on and self.tach_le_chan:
            if prefer not in ("le", "chan"):
                raise ValueError(f"prefer phải là 'le' hoặc 'chan'. Nhận: {prefer!r}")
            kept = self.template_le if prefer == "le" else self.template_chan
            self.template_chinh = kept.clone() if kept else TKBTemplate()
            self.template_le = None
            self.template_chan = None
            self.tach_le_chan = False

    @classmethod
    def empty(
        cls,
        ho_ten_gv: str,
        nam_hoc: int,
        cap_hoc: int,
        cap_hoc_text: str = "",
        ma_truong: str = "",
    ) -> "KHDHProfile":
        """Khởi tạo hồ sơ rỗng — TKB chính chưa có slot, ppct_starts rỗng."""
        return cls(
            ho_ten_gv=ho_ten_gv,
            nam_hoc=nam_hoc,
            cap_hoc=cap_hoc,
            cap_hoc_text=cap_hoc_text,
            ma_truong=ma_truong,
            ngay_tao="",
            ghi_chu="",
            tach_le_chan=False,
            template_chinh=TKBTemplate(slots=[]),
        )


def _legacy_holiday_rules_to_events(
    profile: KHDHProfile,
    rules: list[TKBHolidayRule],
    *,
    skip_invalid: bool,
) -> list[TKBScheduleEvent]:
    """Chuyển quy tắc cũ sang event mới, giữ file Excel cũ còn dùng được."""
    events: list[TKBScheduleEvent] = []
    for rule in rules or []:
        if not getattr(rule, "enabled", True):
            continue
        try:
            source_template = profile.get_active_template(rule.holiday_tuan)
            source_slot = source_template.slot_at(
                rule.holiday_thu, rule.holiday_buoi, rule.holiday_tiet
            )
            if source_slot is None:
                raise ProfileSchemaError(
                    "NghiDayBu.legacy",
                    "Quy tắc cũ không khớp ô TKB nguồn.",
                )
            events.append(TKBScheduleEvent.from_slot(
                kind=TKB_EVENT_NGHI,
                source_slot=source_slot,
                tuan=rule.holiday_tuan,
                thu=rule.holiday_thu,
                buoi=rule.holiday_buoi,
                tiet=rule.holiday_tiet,
                note=rule.note or "Nghỉ",
                enabled=rule.enabled,
            ))
            if rule.has_makeup:
                events.append(TKBScheduleEvent.from_slot(
                    kind=TKB_EVENT_DAY_BU,
                    source_slot=source_slot,
                    tuan=rule.makeup_tuan,
                    thu=rule.makeup_thu,
                    buoi=rule.makeup_buoi,
                    tiet=rule.makeup_tiet,
                    note=rule.note or "Dạy bù",
                    enabled=rule.enabled,
                    replace_normal_slot=True,
                ))
        except ProfileSchemaError:
            if skip_invalid:
                continue
            raise
    return events

def profile_schedule_events(profile: KHDHProfile) -> list[TKBScheduleEvent]:
    """Trả danh sách sự kiện canonical, có adapter cho hồ sơ đời cũ."""
    events = getattr(profile, "schedule_events", None) or []
    if events:
        return [
            e.clone() if isinstance(e, TKBScheduleEvent) else TKBScheduleEvent(**e)
            for e in events
        ]
    return _legacy_holiday_rules_to_events(
        profile,
        getattr(profile, "holiday_rules", []) or [],
        skip_invalid=True,
    )

def count_profile_holiday_rules(
    profile: KHDHProfile, tuan_from: int | None = None, tuan_to: int | None = None
) -> tuple[int, int]:
    """Đếm số tiết Nghỉ và Dạy bù đang bật trong dải tuần."""
    tuan_from = profile.tuan_from if tuan_from is None else int(tuan_from)
    tuan_to = profile.tuan_to if tuan_to is None else int(tuan_to)
    n_nghi = 0
    n_bu = 0
    for event in profile_schedule_events(profile):
        if not event.enabled:
            continue
        if not (tuan_from <= event.tuan <= tuan_to):
            continue
        if event.kind == TKB_EVENT_NGHI:
            n_nghi += 1
        elif event.kind == TKB_EVENT_DAY_BU:
            n_bu += 1
    return n_nghi, n_bu

def validate_profile_schedule_events(
    profile: KHDHProfile, tuan_from: int | None = None, tuan_to: int | None = None
) -> list[tuple[str, str]]:
    """Rà soát sự kiện Nghỉ/Dạy bù trước khi chạy web."""
    tuan_from = profile.tuan_from if tuan_from is None else int(tuan_from)
    tuan_to = profile.tuan_to if tuan_to is None else int(tuan_to)
    warnings: list[tuple[str, str]] = []
    seen_targets: dict[tuple[int, int, int, int], TKBScheduleEvent] = {}

    for event in profile_schedule_events(profile):
        if not event.enabled:
            continue
        pos = event.position_tuple()
        if pos in seen_targets:
            old = seen_targets[pos]
            warnings.append((
                "error",
                f"Trùng vị trí tuần {event.tuan}, thứ {event.thu}, "
                f"buổi {event.buoi}, tiết {event.tiet}: "
                f"{old.label} và {event.label}. Mỗi ô chỉ được có một trạng thái.",
            ))
        seen_targets[pos] = event

        try:
            target_template = profile.get_active_template(event.tuan)
            target_slot = target_template.slot_at(event.thu, event.buoi, event.tiet)
        except Exception:
            target_slot = None

        if event.kind == TKB_EVENT_NGHI:
            if target_slot is None:
                warnings.append((
                    "error",
                    f"Tiết Nghỉ tuần {event.tuan}, thứ {event.thu}, "
                    f"buổi {event.buoi}, tiết {event.tiet} không khớp ô TKB nào.",
                ))
            elif not event.source_matches_slot(target_slot):
                warnings.append((
                    "error",
                    f"Tiết Nghỉ tuần {event.tuan}, thứ {event.thu}, "
                    f"buổi {event.buoi}, tiết {event.tiet} đang không còn đúng "
                    f"{event.source_lop_text} / {event.source_phan_mon_text or event.source_mon_text}.",
                ))
        elif event.kind == TKB_EVENT_DAY_BU:
            if target_slot is not None and not event.replace_normal_slot:
                warnings.append((
                    "error",
                    f"Tiết Dạy bù tuần {event.tuan}, thứ {event.thu}, "
                    f"buổi {event.buoi}, tiết {event.tiet} đang trùng một tiết TKB thường. "
                    "Hãy bật lựa chọn dùng ô này cho Dạy bù hoặc chọn ô trống.",
                ))

        if not (tuan_from <= event.tuan <= tuan_to):
            warnings.append((
                "warn",
                f"{event.label} tuần {event.tuan}, thứ {event.thu}, "
                f"buổi {event.buoi}, tiết {event.tiet} nằm ngoài dải tuần đang chạy.",
            ))
    return warnings

def validate_profile_holiday_rules(
    profile: KHDHProfile, tuan_from: int | None = None, tuan_to: int | None = None
) -> list[tuple[str, str]]:
    """Tên cũ giữ tương thích; logic mới dùng `TKBScheduleEvent`."""
    warnings = validate_profile_schedule_events(profile, tuan_from, tuan_to)
    if not getattr(profile, "schedule_events", None):
        for rule in getattr(profile, "holiday_rules", []) or []:
            if not getattr(rule, "enabled", True):
                continue
            try:
                template = profile.get_active_template(rule.holiday_tuan)
                source_slot = template.slot_at(
                    rule.holiday_thu, rule.holiday_buoi, rule.holiday_tiet
                )
            except Exception:
                source_slot = None
            if source_slot is None:
                warnings.append((
                    "error",
                    f"Quy tắc cũ tuần {rule.holiday_tuan}, thứ {rule.holiday_thu}, "
                    f"buổi {rule.holiday_buoi}, tiết {rule.holiday_tiet} không khớp ô TKB nào.",
                ))
    return warnings

