@dataclass
class BackupFile:
    """Toàn bộ file backup. Top-level container."""
    metadata: BackupMetadata = field(default_factory=BackupMetadata)
    weeks: list[BackupWeek] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {
            "version": BACKUP_FORMAT_VERSION,
            "kind": BACKUP_FILE_KIND,
            "metadata": self.metadata.to_dict(),
            "weeks": [w.to_dict() for w in self.weeks],
        }

    @classmethod
    def from_dict(cls, d: dict) -> "BackupFile":
        return cls(
            metadata=BackupMetadata.from_dict(d.get("metadata") or {}),
            weeks=[BackupWeek.from_dict(w) for w in (d.get("weeks") or [])],
        )

    @property
    def total_filled_slots(self) -> int:
        return sum(w.filled_count for w in self.weeks)

    @property
    def total_slots(self) -> int:
        return sum(len(w.slots) for w in self.weeks)

    def week_by_num(self, tuan: int) -> "BackupWeek | None":
        for w in self.weeks:
            if int(w.tuan) == int(tuan):
                return w
        return None


class BackupSchemaError(Exception):
    """File backup không hợp lệ — schema sai hoặc cấu trúc lạ."""


def save_backup_json(bf: BackupFile, path: str | Path) -> None:
    """Atomic write: tmp → replace. Tránh corrupt nếu crash giữa chừng.

    JSON có indent=2 để diff dễ; file 36 tuần × 25 slots ~ 200KB.
    """
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_suffix(p.suffix + ".tmp")
    payload = bf.to_dict()
    try:
        tmp.write_text(
            json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=False),
            encoding="utf-8",
        )
        os.replace(tmp, p)
    except Exception:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        raise


def load_backup_json(path: str | Path) -> BackupFile:
    """Đọc + validate. Raise BackupSchemaError nếu không hợp lệ."""
    p = Path(path)
    if not p.exists():
        raise FileNotFoundError(str(p))
    try:
        text = p.read_text(encoding="utf-8")
    except Exception as e:
        raise BackupSchemaError(f"Không đọc được file: {e}")
    try:
        data = json.loads(text)
    except Exception as e:
        raise BackupSchemaError(
            f"File không phải JSON hợp lệ: {e}\n"
            "Có thể file đã bị hỏng hoặc bị edit tay sai cú pháp."
        )
    if not isinstance(data, dict):
        raise BackupSchemaError("File không phải dict JSON.")
    kind = str(data.get("kind") or "")
    if kind != BACKUP_FILE_KIND:
        raise BackupSchemaError(
            f"File không phải backup KHDH (kind='{kind}', "
            f"phải là '{BACKUP_FILE_KIND}')."
        )
    version = data.get("version")
    if not isinstance(version, int) or version < 1:
        raise BackupSchemaError(
            f"Version không hợp lệ: {version!r}. Phải là số ≥ 1."
        )
    if version > BACKUP_FORMAT_VERSION:
        # Forward-compat: chấp nhận file v2/v3 nhưng warning ở caller
        pass
    return BackupFile.from_dict(data)


# ######################################################################
# KHBD Logic Engine — audit / repair / diff trên backup hoặc Excel review
# ######################################################################

KHBD_ISSUE_ACTIVE_DUP = "active_duplicate"
KHBD_ISSUE_PPCT_GAP = "ppct_gap"
KHBD_ISSUE_PPCT_ORDER = "ppct_order"
KHBD_ISSUE_OVER_CAP = "over_cap"
KHBD_ISSUE_NGHI_NO_MAKEUP = "nghi_no_makeup"
KHBD_ISSUE_TITLE_CONFLICT = "title_conflict"


@dataclass
class KHBDAuditIssue:
    """Một lỗi/cảnh báo dữ liệu KHBD trước khi import hoặc ghi web."""
    severity: str
    kind: str
    tuan: int
    row_key: str
    group_key: str
    label: str
    ppct: str = ""
    message: str = ""


@dataclass
class KHBDRepairAction:
    """Một đề xuất sửa offline, chỉ áp dụng khi user duyệt preview."""
    tuan: int
    row_key: str
    group_key: str
    label: str
    current_ppct: str = ""
    proposed_ppct: str = ""
    current_ten_bai: str = ""
    proposed_ten_bai: str = ""
    current_status: str = ""
    proposed_status: str = ""
    note: str = ""
    skip: bool = False

    @property
    def needs_change(self) -> bool:
        return (
            str(self.current_ppct or "") != str(self.proposed_ppct or "")
            or str(self.current_ten_bai or "") != str(self.proposed_ten_bai or "")
            or (
                bool(self.proposed_status)
                and str(self.current_status or "") != str(self.proposed_status or "")
            )
        )


@dataclass
class KHBDAuditResult:
    """Kết quả audit tổng hợp của KHBD Logic Engine."""
    issues: list[KHBDAuditIssue] = field(default_factory=list)
    groups_checked: int = 0
    slots_checked: int = 0

    @property
    def error_count(self) -> int:
        return sum(1 for i in self.issues if i.severity == SEVERITY_ERROR)

    @property
    def warning_count(self) -> int:
        return sum(1 for i in self.issues if i.severity == SEVERITY_WARNING)

    @property
    def blocker_count(self) -> int:
        return self.error_count


