        tree_frm.grid(row=3, column=0, sticky="nsew", pady=(0, 6))
        tree_frm.rowconfigure(1, weight=1)
        tree_frm.columnconfigure(0, weight=1)

        bar = ttk.Frame(tree_frm, style="Wiz.TFrame")
        bar.grid(row=0, column=0, sticky="ew", pady=(0, 4))
